.bks-annual {
  /* re-theme with these four */
  --bks-annual-paper: oklch(96.6% 0.014 84);
  --bks-annual-ink: oklch(22% 0.02 55);
  --bks-annual-accent: oklch(53% 0.17 32);
  --bks-annual-serif: ui-serif, "New York", "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  --bks-annual-muted: color-mix(in oklch, var(--bks-annual-ink) 62%, var(--bks-annual-paper));
  --bks-annual-rule: color-mix(in oklch, var(--bks-annual-ink) 16%, var(--bks-annual-paper));
  --bks-annual-tint: color-mix(in oklch, var(--bks-annual-accent) 9%, var(--bks-annual-paper));
  --bks-annual-past: color-mix(in oklch, var(--bks-annual-ink) 34%, var(--bks-annual-paper));
  --bks-annual-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bks-annual-out: cubic-bezier(.16, 1, .3, 1);
  --bks-annual-spring: linear(0, 0.042, 0.145, 0.283, 0.433, 0.579, 0.712, 0.826, 0.917, 0.985, 1.033, 1.063, 1.079, 1.084, 1.08, 1.071, 1.06, 1.047, 1.035, 1.024, 1.015, 1.007, 1.001, 0.997, 0.995, 0.993, 0.993, 0.993, 0.994, 0.995, 0.996, 0.997, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-annual-paper);
  color: var(--bks-annual-ink);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dt, dd, ol, li, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
}

.bks-annual-in {
  padding: clamp(36px, 7cqi, 96px) clamp(16px, 5.5cqi, 72px) clamp(32px, 5cqi, 64px);
  display: grid;
  gap: clamp(28px, 4.5cqi, 56px);
}

.bks-annual-sr {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

/* ---------- header ---------- */
.bks-annual-head {
  display: grid;
  gap: 18px 6cqi;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "kicker" "title" "lede" "pick";
}
.bks-annual-kicker {
  grid-area: kicker;
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--bks-annual-ink);
  font: 500 11px/1 var(--bks-annual-mono);
  letter-spacing: .14em; text-transform: uppercase;
  color: var(--bks-annual-muted);
}
.bks-annual-brand {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--bks-annual-ink); font-weight: 700; letter-spacing: .18em;
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bks-annual-accent); stroke-width: 1.6; stroke-linecap: round; }
}
.bks-annual-title {
  grid-area: title;
  font: 400 clamp(40px, 5.2cqi + 14px, 76px)/.98 var(--bks-annual-serif);
  letter-spacing: -.025em;
  text-wrap: balance;
  max-width: 14ch;
  & em { font-style: italic; color: var(--bks-annual-accent); white-space: nowrap; }
}
.bks-annual-lede {
  grid-area: lede;
  max-width: 46ch;
  font-size: clamp(15px, .5cqi + 13px, 17px);
  color: color-mix(in oklch, var(--bks-annual-ink) 80%, var(--bks-annual-paper));
  text-wrap: pretty;
}
.bks-annual-pick {
  grid-area: pick;
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
}
.bks-annual-span {
  font: 500 12px/1.3 var(--bks-annual-mono);
  color: var(--bks-annual-muted);
  font-variant-numeric: tabular-nums;
}

/* segmented control: native radios, the thumb follows :has(:checked) */
.bks-annual-years {
  --bks-annual-sel: 2;
  position: relative;
  display: grid; grid-template-columns: repeat(3, 64px);
  padding: 3px;
  border: 1px solid var(--bks-annual-ink);
  border-radius: 999px;
  isolation: isolate;
  &:has(input[value="1"]:checked) { --bks-annual-sel: 0; }
  &:has(input[value="2"]:checked) { --bks-annual-sel: 1; }
  &:has(input[value="3"]:checked) { --bks-annual-sel: 2; }
  & label { position: relative; display: grid; place-items: center; height: 34px; cursor: pointer; }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; accent-color: var(--bks-annual-accent); }
  & span {
    font: 600 13px/1 var(--bks-annual-mono); letter-spacing: .04em;
    color: var(--bks-annual-ink);
    transition: color .35s var(--bks-annual-out);
  }
  & input:checked + span { color: var(--bks-annual-paper); }
  & label:hover input:not(:checked) + span { color: var(--bks-annual-accent); }
  &:has(input:focus-visible) { outline: 2px solid var(--bks-annual-accent); outline-offset: 3px; }
}
.bks-annual-thumb {
  position: absolute; z-index: -1;
  top: 3px; left: 3px; width: 64px; height: 34px;
  border-radius: 999px;
  background: var(--bks-annual-ink);
  translate: calc(var(--bks-annual-sel) * 64px) 0;
  transition: translate .62s var(--bks-annual-spring);
}

/* ---------- stats: one subgrid row-set per stat so every line aligns across columns ---------- */
.bks-annual-stats {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1px;
  background: var(--bks-annual-rule);
  border-block: 1px solid var(--bks-annual-rule);
}
.bks-annual-stat {
  grid-row: span 4;
  display: grid;
  grid-template-rows: subgrid;
  row-gap: 10px;
  align-items: end;
  padding: 22px 0 24px;
  background: var(--bks-annual-paper);
  transition: background-color .4s var(--bks-annual-out);
  & dt {
    align-self: start;
    font: 600 11px/1.35 var(--bks-annual-mono);
    letter-spacing: .1em; text-transform: uppercase;
    color: var(--bks-annual-muted);
    text-wrap: balance;
  }
  & sup { font-size: 9px; color: var(--bks-annual-accent); margin-left: 2px; vertical-align: 4px; line-height: 0; }
}
.bks-annual-fig {
  /* the figure sizes itself to its own column, not to the section */
  container-type: inline-size;
  position: relative;
  padding-bottom: 14px;
  & span {
    display: block;
    font: 400 clamp(38px, 21cqi, 64px)/.95 var(--bks-annual-serif);
    letter-spacing: -.035em;
    font-variant-numeric: tabular-nums lining-nums;
    white-space: nowrap;
  }
  &::after {
    content: ""; position: absolute; left: 0; bottom: 0;
    width: 40px; height: 2px; background: var(--bks-annual-accent);
    transform-origin: left;
    transition: scale .9s var(--bks-annual-out) calc(var(--i) * 110ms + 200ms);
  }
}
.bks-annual-delta {
  display: flex; align-items: center; gap: 6px;
  font: 500 13px/1 system-ui, sans-serif;
  font-variant-numeric: tabular-nums;
  & svg { width: 12px; height: 12px; fill: none; stroke: var(--bks-annual-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & b { font-weight: 650; }
  & span { color: var(--bks-annual-muted); }
}
.bks-annual-bars {
  display: flex; align-items: flex-end; gap: 12px;
  padding-top: 6px;
  & small { font: 500 10.5px/1.2 var(--bks-annual-mono); color: var(--bks-annual-muted); letter-spacing: .04em; padding-bottom: 1px; }
}
.bks-annual-barset {
  display: flex; align-items: flex-end; gap: 4px; height: 40px;
  & i {
    width: 10px; height: calc(var(--h) * 100%); min-height: 2px;
    background: var(--bks-annual-past);
    transform-origin: bottom;
    transition:
      scale .8s var(--bks-annual-spring) calc(var(--i) * 110ms + var(--j) * 55ms + 250ms),
      background-color .4s var(--bks-annual-out),
      box-shadow .4s var(--bks-annual-out);
  }
  & i.is-now { background: var(--bks-annual-accent); }
  & i.is-next { background: transparent; box-shadow: inset 0 0 0 1px var(--bks-annual-past); }
}

/* armed by JS: hold the reveal until the band scrolls into view */
.bks-annual.is-armed:not(.is-in) {
  & .bks-annual-barset i { scale: 1 0; }
  & .bks-annual-fig::after { scale: 0 1; }
}

/* ---------- footnotes, cross-linked to their stat with :has() ---------- */
.bks-annual-notes {
  list-style: none;
  display: grid; gap: 8px 40px;
  grid-template-columns: minmax(0, 1fr);
  font-size: 12.5px; line-height: 1.5;
  color: var(--bks-annual-muted);
  counter-reset: bks-annual-fn;
  & li {
    counter-increment: bks-annual-fn;
    display: grid; grid-template-columns: 18px 1fr;
    padding: 4px 6px; margin-inline: -6px;
    border-radius: 4px;
    text-wrap: pretty;
    transition: background-color .3s var(--bks-annual-out), color .3s var(--bks-annual-out);
    &::before { content: counter(bks-annual-fn); color: var(--bks-annual-accent); font: 600 11px/1.7 var(--bks-annual-mono); }
  }
}
.bks-annual:has(.bks-annual-stat[data-fn="1"]:hover) .bks-annual-notes li[data-fn="1"],
.bks-annual:has(.bks-annual-stat[data-fn="2"]:hover) .bks-annual-notes li[data-fn="2"],
.bks-annual:has(.bks-annual-stat[data-fn="3"]:hover) .bks-annual-notes li[data-fn="3"],
.bks-annual:has(.bks-annual-stat[data-fn="4"]:hover) .bks-annual-notes li[data-fn="4"] {
  background: var(--bks-annual-tint); color: var(--bks-annual-ink);
}
.bks-annual:has(.bks-annual-notes li[data-fn="1"]:hover) .bks-annual-stat[data-fn="1"],
.bks-annual:has(.bks-annual-notes li[data-fn="2"]:hover) .bks-annual-stat[data-fn="2"],
.bks-annual:has(.bks-annual-notes li[data-fn="3"]:hover) .bks-annual-stat[data-fn="3"],
.bks-annual:has(.bks-annual-notes li[data-fn="4"]:hover) .bks-annual-stat[data-fn="4"],
.bks-annual-stat:hover {
  background: var(--bks-annual-tint);
}

/* ---------- container breakpoints ---------- */
@container (min-width: 560px) {
  .bks-annual-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bks-annual-stat { padding-inline: 20px; }
  .bks-annual-notes { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container (min-width: 880px) {
  .bks-annual-head {
    grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
    grid-template-areas: "kicker kicker" "title lede" "title pick";
    align-items: end;
  }
  .bks-annual-title { align-self: start; }
  .bks-annual-stats { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bks-annual-stat { padding: 26px 22px 28px; }
  .bks-annual-stat:first-child { padding-left: 0; }
  .bks-annual-notes { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .bks-annual {
    & .bks-annual-thumb, & .bks-annual-barset i, & .bks-annual-fig::after { transition-duration: .01s; transition-delay: 0s; }
  }
  .bks-annual.is-armed:not(.is-in) {
    & .bks-annual-barset i { scale: 1; }
    & .bks-annual-fig::after { scale: 1; }
  }
}

js:
// One source of truth: FY23 exists only so FY24 has something to compare against.
const YEARS = ['FY23', 'FY24', 'FY25', 'FY26'];
const SPANS = ['1 Oct 2022 – 30 Sep 2023', '1 Oct 2023 – 30 Sep 2024', '1 Oct 2024 – 30 Sep 2025', '1 Oct 2025 – 30 Sep 2026'];
const STATS = [
  { name: 'Payroll processed', v: [2.61, 4.82, 7.36, 11.94], fmt: 'usdB' },
  { name: 'Businesses running payroll', v: [9870, 18240, 31605, 52118], fmt: 'int' },
  { name: 'People paid', v: [214600, 402900, 811450, 1486300], fmt: 'int' },
  // the bars show what the rate hides: late runs per 10,000 = (100 - rate) * 100
  { name: 'Payrolls paid on time', v: [99.64, 99.82, 99.91, 99.97], fmt: 'pct', bars: (r) => Math.round((100 - r) * 100) }
];

const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const nf = new Intl.NumberFormat('en-US');
const FMT = {
  usdB: (v) => '$' + v.toFixed(2) + 'B',
  int: (v) => nf.format(Math.round(v)),
  pct: (v) => v.toFixed(2) + '%'
};
const statEls = [...root.querySelectorAll('.bks-annual-stat')];
const figs = statEls.map((s) => s.querySelector('.bks-annual-fig span'));
const deltas = statEls.map((s) => s.querySelector('.bks-annual-delta'));
const bars = statEls.map((s) => [...s.querySelectorAll('.bks-annual-barset i')]);
const radios = [...root.querySelectorAll('.bks-annual-years input')];
const spanEl = root.querySelector('.bks-annual-span');
const live = root.querySelector('[aria-live]');

// radios group by name document-wide; give each mounted copy its own group
const uid = Math.random().toString(36).slice(2, 8);
radios.forEach((r) => { r.name = 'bks-annual-fy-' + uid; });

// bar heights come from the same numbers as the figures
STATS.forEach((s, k) => {
  const series = s.bars ? s.v.map(s.bars) : s.v;
  const max = Math.max(...series);
  bars[k].forEach((b, j) => b.style.setProperty('--h', (series[j] / max).toFixed(3)));
});

let sel = radios.findIndex((r) => r.checked) + 1 || 3;
let shown = STATS.map(() => 0);
let tweens = [];
let raf = 0;

const fmt = (k, v) => FMT[STATS[k].fmt](v);
const expoOut = (p) => (p >= 1 ? 1 : 1 - Math.pow(2, -10 * p));

function deltaText(k, y) {
  const s = STATS[k], cur = s.v[y], prev = s.v[y - 1];
  if (s.fmt === 'pct') {
    const d = cur - prev;
    return (d >= 0 ? '+' : '−') + Math.abs(d).toFixed(2) + ' pts';
  }
  const d = (cur / prev - 1) * 100;
  return (d >= 0 ? '+' : '−') + Math.abs(d).toFixed(1) + '%';
}

function paintStatic(y, animate) {
  spanEl.textContent = SPANS[y];
  STATS.forEach((s, k) => {
    const b = deltas[k].querySelector('b'), lab = deltas[k].querySelector('span');
    const next = deltaText(k, y), vs = 'vs ' + YEARS[y - 1];
    if (b.textContent !== next) {
      b.textContent = next; lab.textContent = vs;
      if (animate && !reduce.matches) {
        deltas[k].animate(
          [{ opacity: 0, transform: 'translateY(6px)', filter: 'blur(3px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
          { duration: 420, delay: k * 60, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }
        );
      }
    }
    bars[k].forEach((bar, j) => {
      bar.classList.toggle('is-now', j === y);
      bar.classList.toggle('is-next', j > y);
    });
  });
}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  let running = false;
  tweens.forEach((t, k) => {
    const p = Math.min(1, Math.max(0, (now - t.start) / t.dur));
    shown[k] = t.from + (t.to - t.from) * expoOut(p);
    const s = fmt(k, shown[k]);
    if (figs[k].textContent !== s) figs[k].textContent = s;
    if (p < 1) running = true;
  });
  if (running) raf = requestAnimationFrame(step);
}

function countTo(y, dur, stagger) {
  if (reduce.matches) {
    STATS.forEach((s, k) => { shown[k] = s.v[y]; figs[k].textContent = fmt(k, shown[k]); });
    return;
  }
  const t0 = performance.now();
  tweens = STATS.map((s, k) => ({ from: shown[k], to: s.v[y], start: t0 + k * stagger, dur }));
  if (!raf) raf = requestAnimationFrame(step);
}

radios.forEach((r) => r.addEventListener('change', () => {
  if (!r.checked) return;
  sel = +r.value;
  paintStatic(sel, true);
  countTo(sel, 900, 70);
  live.textContent = YEARS[sel] + ': ' + STATS.map((s, k) => s.name + ' ' + fmt(k, s.v[sel])).join(', ') + '.';
}));

paintStatic(sel, false);

if (reduce.matches || !('IntersectionObserver' in window)) {
  root.classList.add('is-in');
  countTo(sel, 0, 0);
  STATS.forEach((s, k) => { shown[k] = s.v[sel]; figs[k].textContent = fmt(k, shown[k]); });
} else {
  // hold the figures at zero until the band is genuinely on screen, then count once
  root.classList.add('is-armed');
  figs.forEach((f, k) => { f.textContent = fmt(k, 0); });
  const io = new IntersectionObserver((entries) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (!entries.some((e) => e.isIntersecting)) return;
    io.disconnect();
    root.classList.add('is-in');
    countTo(sel, 1500, 110);
  }, { threshold: 0.3 });
  io.observe(root.querySelector('.bks-annual-stats'));
}

css:
.bks-wall {
  /* re-theme with these four */
  --bks-wall-bg: oklch(98.7% 0.004 95);
  --bks-wall-ink: oklch(21% 0.014 265);
  --bks-wall-accent: oklch(62% 0.16 152);
  --bks-wall-radius: 18px;

  --bks-wall-logo-ink: color-mix(in oklch, var(--bks-wall-ink) 56%, var(--bks-wall-bg));
  --bks-wall-muted: color-mix(in oklch, var(--bks-wall-ink) 62%, var(--bks-wall-bg));
  --bks-wall-rule: color-mix(in oklch, var(--bks-wall-ink) 9%, var(--bks-wall-bg));
  --bks-wall-cellbg: var(--bks-wall-bg);
  --bks-wall-hover: color-mix(in oklch, var(--bks-wall-ink) 3.5%, var(--bks-wall-bg));
  --bks-wall-out: cubic-bezier(.16, 1, .3, 1);
  --bks-wall-spring: linear(0, 0.042, 0.145, 0.283, 0.433, 0.579, 0.712, 0.826, 0.917, 0.985, 1.033, 1.063, 1.079, 1.084, 1.08, 1.071, 1.06, 1.047, 1.035, 1.024, 1.015, 1.007, 1.001, 0.997, 0.995, 0.993, 0.993, 0.993, 0.994, 0.995, 0.996, 0.997, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-wall-bg);
  color: var(--bks-wall-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, li) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; }
}

.bks-wall-in {
  padding: clamp(40px, 7cqi, 96px) clamp(16px, 5cqi, 64px) clamp(28px, 4.5cqi, 56px);
  display: grid; gap: clamp(28px, 4cqi, 48px);
}

/* ---------- header ---------- */
.bks-wall-head {
  display: grid; gap: 16px 6cqi;
  grid-template-areas: "kicker" "title" "lede" "pause";
  justify-items: start;
}
.bks-wall-kicker {
  grid-area: kicker;
  display: inline-flex; align-items: center; gap: 10px;
  font: 600 12px/1 system-ui, sans-serif; letter-spacing: .08em; text-transform: uppercase;
  color: var(--bks-wall-muted);
}
.bks-wall-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--bks-wall-accent);
  box-shadow: 0 0 0 0 color-mix(in oklch, var(--bks-wall-accent) 50%, transparent);
  animation: bks-wall-ping 2.8s cubic-bezier(.2, .7, .3, 1) infinite;
  transition: background-color .3s;
}
@keyframes bks-wall-ping {
  0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--bks-wall-accent) 55%, transparent); }
  60%, 100% { box-shadow: 0 0 0 9px color-mix(in oklch, var(--bks-wall-accent) 0%, transparent); }
}
.bks-wall:has(.bks-wall-pause[aria-pressed="true"]) .bks-wall-dot { animation: none; background: var(--bks-wall-logo-ink); }

.bks-wall-title {
  grid-area: title;
  font: 700 clamp(30px, 3.4cqi + 16px, 54px)/1.02 system-ui, -apple-system, sans-serif;
  letter-spacing: -.038em;
  text-wrap: balance;
  max-width: 16ch;
}
.bks-wall-lede {
  grid-area: lede;
  max-width: 44ch;
  color: var(--bks-wall-muted);
  font-size: clamp(15px, .4cqi + 13.5px, 17px);
  text-wrap: pretty;
}
.bks-wall-pause {
  grid-area: pause;
  display: inline-flex; align-items: center; gap: 8px;
  height: 36px; padding: 0 14px 0 11px;
  border: 1px solid var(--bks-wall-rule); border-radius: 999px;
  background: var(--bks-wall-bg);
  font-size: 13px; font-weight: 550;
  cursor: pointer;
  transition: background-color .25s var(--bks-wall-out), border-color .25s;
  & svg { width: 16px; height: 16px; }
  & .bks-wall-ip { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  & .bks-wall-iy { fill: currentColor; display: none; }
  &[aria-pressed="true"] .bks-wall-ip { display: none; }
  &[aria-pressed="true"] .bks-wall-iy { display: inline; }
  &:hover { background: var(--bks-wall-hover); border-color: color-mix(in oklch, var(--bks-wall-ink) 22%, var(--bks-wall-bg)); }
  &:focus-visible { outline: 2px solid var(--bks-wall-ink); outline-offset: 2px; }
}

/* ---------- the wall ---------- */
.bks-wall-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  background: var(--bks-wall-rule);
  border: 1px solid var(--bks-wall-rule);
  border-radius: var(--bks-wall-radius);
  overflow: clip;
  & li { display: grid; }
}
.bks-wall-cell {
  position: relative;
  display: grid; place-items: center;
  height: clamp(78px, 9cqi + 30px, 124px);
  border: 0; padding: 0;
  background: var(--bks-wall-cellbg);
  overflow: hidden;
  cursor: pointer;
  transition: background-color .3s var(--bks-wall-out);
  &:hover, &[aria-expanded="true"] { --bks-wall-cellbg: var(--bks-wall-hover); }
  &:focus-visible { outline: 2px solid var(--bks-wall-ink); outline-offset: -4px; border-radius: 10px; }
}
.bks-wall-logo {
  grid-area: 1 / 1;
  height: clamp(17px, 1.2cqi + 12px, 27px);
  width: auto; max-width: 82%;
  overflow: visible;
  color: var(--bks-wall-logo-ink);
  fill: currentColor;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  transition: color .35s var(--bks-wall-out), opacity .35s var(--bks-wall-out);
  & .bks-wall-mk { transition: color .35s var(--bks-wall-out); }
  & .bks-wall-cut { stroke: var(--bks-wall-cellbg); transition: stroke .3s var(--bks-wall-out); }
}
.bks-wall-cell:is(:hover, :focus-visible, [aria-expanded="true"]) .bks-wall-logo {
  color: var(--bks-wall-ink);
  & .bks-wall-mk { color: oklch(57% 0.15 var(--hue)); }
}
/* everything else steps back while one logo has the floor */
.bks-wall-grid:has(.bks-wall-cell:is(:hover, [aria-expanded="true"])) .bks-wall-cell:not(:hover, [aria-expanded="true"]) .bks-wall-logo { opacity: .5; }

/* ---------- detail card (absolute inside the root, never top-layer) ---------- */
.bks-wall-card {
  --ax: 50%;
  position: absolute; left: 0; top: 0; z-index: 3;
  width: min(290px, calc(100% - 24px));
  padding: 16px 18px 18px;
  border-radius: 14px;
  background: var(--bks-wall-ink);
  color: var(--bks-wall-bg);
  box-shadow: 0 18px 40px -12px color-mix(in oklch, var(--bks-wall-ink) 45%, transparent), 0 2px 6px color-mix(in oklch, var(--bks-wall-ink) 18%, transparent);
  opacity: 0; scale: .96;
  transform-origin: var(--ax) 0;
  pointer-events: none;
  transition: opacity .18s var(--bks-wall-out), scale .4s var(--bks-wall-spring), translate .45s var(--bks-wall-out);
  &.is-open { opacity: 1; scale: 1; pointer-events: auto; }
  &.is-above { transform-origin: var(--ax) 100%; }
  & p { position: relative; }
}
.bks-wall-caret {
  position: absolute; top: -5px; left: calc(var(--ax) - 6px);
  width: 12px; height: 12px; rotate: 45deg; border-radius: 2px;
  background: var(--bks-wall-ink);
  .bks-wall-card.is-above & { top: auto; bottom: -5px; }
}
.bks-wall-cname { font-weight: 650; font-size: 15px; letter-spacing: -.01em; }
.bks-wall-cmeta { font-size: 12px; color: color-mix(in oklch, var(--bks-wall-bg) 62%, var(--bks-wall-ink)); margin-top: 2px; }
.bks-wall-cbig {
  margin-top: 14px;
  font: 700 34px/1 system-ui, sans-serif; letter-spacing: -.04em;
  font-variant-numeric: tabular-nums;
  color: color-mix(in oklch, var(--bks-wall-accent) 70%, var(--bks-wall-bg));
}
.bks-wall-clab { font-size: 13px; margin-top: 4px; text-wrap: pretty; }

/* ---------- footer ---------- */
.bks-wall-foot {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 28px;
  font-size: 13.5px; color: var(--bks-wall-muted);
  font-variant-numeric: tabular-nums;
  & b { color: var(--bks-wall-ink); font-weight: 650; }
}
.bks-wall-status { flex-basis: 100%; font-size: 12px; }

@container (min-width: 620px) {
  .bks-wall-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bks-wall-status { flex-basis: auto; margin-left: auto; }
}
@container (min-width: 920px) {
  .bks-wall-head {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    grid-template-areas: "kicker kicker" "title lede" "title pause";
    align-items: end;
  }
  .bks-wall-title { align-self: start; }
  .bks-wall-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .bks-wall {
    & .bks-wall-dot { animation: none; }
    & .bks-wall-card { transition: opacity .15s linear; scale: 1; }
    & .bks-wall-pause { display: none; }
  }
}

