const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const grid = root.querySelector('.bks-wall-grid');
const cells = [...root.querySelectorAll('.bks-wall-cell')];
const card = root.querySelector('.bks-wall-card');
const cName = card.querySelector('.bks-wall-cname');
const cMeta = card.querySelector('.bks-wall-cmeta');
const cBig = card.querySelector('.bks-wall-cbig');
const cLab = card.querySelector('.bks-wall-clab');
const pauseBtn = root.querySelector('.bks-wall-pause');
const status = root.querySelector('.bks-wall-status');

const uid = Math.random().toString(36).slice(2, 8);
card.id = 'bks-wall-card-' + uid;
cells.forEach((c) => c.setAttribute('aria-describedby', card.id));

// Wordmarks are live SVG text, so their width depends on the system font:
// measure each one and fit its viewBox instead of guessing.
function fit(svg) {
  try {
    const b = svg.getBBox();
    if (b.width > 0) svg.setAttribute('viewBox', '0 0 ' + Math.ceil(b.x + b.width + 1) + ' 24');
  } catch (e) { /* not rendered yet */ }
}
cells.forEach((c) => fit(c.querySelector('svg')));

const onWall = cells.map((c) => +c.dataset.k);
const queue = LOGOS.map((_, k) => k).filter((k) => !onWall.includes(k));
const recent = [];
let active = -1, pinned = false, hovering = false, focusIn = false, userPaused = false, visible = true;
let hoverT = 0;

const cols = () => getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length;

/* ---------- detail card ---------- */
function fill(k) {
  const L = LOGOS[k];
  cName.textContent = L.n;
  cMeta.textContent = L.ind + ' · since ' + L.since + ' · ' + L.ent + (L.ent === 1 ? ' entity' : ' entities');
  cBig.textContent = L.big;
  cLab.textContent = L.lab;
}
function place(i) {
  const r = cells[i].getBoundingClientRect();
  const R = root.getBoundingClientRect();
  const cw = card.offsetWidth, ch = card.offsetHeight;
  const cx = r.left - R.left + r.width / 2;
  const x = Math.max(12, Math.min(R.width - cw - 12, cx - cw / 2));
  let y = r.bottom - R.top + 10;
  const above = y + ch > R.height - 8;
  if (above) y = r.top - R.top - ch - 10;
  card.classList.toggle('is-above', above);
  card.style.setProperty('--ax', Math.round(cx - x) + 'px');
  card.style.translate = Math.round(x) + 'px ' + Math.round(y) + 'px';
}
function show(i) {
  const open = card.classList.contains('is-open');
  const changed = active !== i;
  active = i;
  fill(+cells[i].dataset.k);
  if (!open) {
    // first appearance: jump to the cell, then fade/scale in from there
    card.style.transition = 'none';
    place(i);
    void card.offsetWidth;
    card.style.transition = '';
    card.classList.add('is-open');
  } else {
    place(i);
    if (changed && !reduce.matches) {
      card.querySelectorAll('p').forEach((p, n) => p.animate(
        [{ opacity: 0, transform: 'translateY(4px)' }, { opacity: 1, transform: 'none' }],
        { duration: 300, delay: n * 30, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }));
    }
  }
