  cells.forEach((c) => c.setAttribute('aria-expanded', 'false'));
}

grid.addEventListener('pointerover', (e) => {
  const c = e.target.closest('.bks-wall-cell');
  if (!c || e.pointerType === 'touch') return;
  hovering = true;
  clearTimeout(hoverT);
  if (pinned) return;
  const i = cells.indexOf(c);
  if (i === active) return;
  hoverT = setTimeout(() => show(i), card.classList.contains('is-open') ? 0 : 140);
});
grid.addEventListener('pointerleave', () => {
  hovering = false;
  clearTimeout(hoverT);
  if (!pinned && !focusIn) hoverT = setTimeout(hide, 180);
});
grid.addEventListener('click', (e) => {
  const c = e.target.closest('.bks-wall-cell');
  if (!c) return;
  const i = cells.indexOf(c);
  if (pinned && active === i) { hide(); return; }
  clearTimeout(hoverT);
  pinned = true;
  show(i);
  cells.forEach((x, j) => x.setAttribute('aria-expanded', String(j === i)));
});
root.addEventListener('pointerdown', (e) => {
  if (pinned && !e.target.closest('.bks-wall-cell, .bks-wall-card')) hide();
});

/* ---------- roving focus across the grid, whatever its column count ---------- */
function rove(c) { cells.forEach((x) => { x.tabIndex = x === c ? 0 : -1; }); }
grid.addEventListener('focusin', (e) => {
  const c = e.target.closest('.bks-wall-cell');
  if (!c) return;
  focusIn = true;
  rove(c);
  if (!pinned) show(cells.indexOf(c));
});
grid.addEventListener('focusout', (e) => {
  if (grid.contains(e.relatedTarget)) return;
  focusIn = false;
  if (!pinned && !hovering) hide();
});
grid.addEventListener('keydown', (e) => {
  const c = e.target.closest('.bks-wall-cell');
  if (!c) return;
  const i = cells.indexOf(c), n = cells.length, w = cols();
  let j;
  switch (e.key) {
    case 'ArrowRight': j = Math.min(n - 1, i + 1); break;
    case 'ArrowLeft': j = Math.max(0, i - 1); break;
    case 'ArrowDown': j = i + w < n ? i + w : i; break;
    case 'ArrowUp': j = i - w >= 0 ? i - w : i; break;
    case 'Home': j = e.ctrlKey ? 0 : i - (i % w); break;
    case 'End': j = e.ctrlKey ? n - 1 : Math.min(n - 1, i - (i % w) + w - 1); break;
    case 'Escape': if (active !== -1) { e.preventDefault(); hide(); } return;
    default: return;
  }
  e.preventDefault();
  if (pinned) { pinned = false; cells.forEach((x) => x.setAttribute('aria-expanded', 'false')); }
  cells[j].focus();
});

/* ---------- rotation ---------- */
function swapOne() {
  const pool = cells.map((_, i) => i).filter((i) => !recent.includes(i));
  const i = pool[Math.floor(Math.random() * pool.length)];
  recent.push(i);
  if (recent.length > 5) recent.shift();
  const inK = queue.shift();
  queue.push(onWall[i]);
  onWall[i] = inK;

  const cell = cells[i];
  const old = cell.querySelector('.bks-wall-logo:not(.is-leaving)');
  const t = document.createElement('template');
  t.innerHTML = LOGOS[inK].svg;
  const neu = t.content.firstElementChild;
  cell.appendChild(neu);
  fit(neu);
  cell.dataset.k = inK;
  cell.setAttribute('aria-label', LOGOS[inK].n);
  if (!old) return;
  old.classList.add('is-leaving');
  old.animate(
    [{ transform: 'none', opacity: 1, filter: 'blur(0)' }, { transform: 'translateY(-60%)', opacity: 0, filter: 'blur(6px)' }],
    { duration: 440, easing: 'cubic-bezier(.64,0,.78,0)', fill: 'forwards' }
  ).finished.then(() => old.remove(), () => old.remove());
  neu.animate(
    [{ transform: 'translateY(60%)', opacity: 0, filter: 'blur(6px)' }, { transform: 'none', opacity: 1, filter: 'blur(0)' }],
    { duration: 700, delay: 200, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }
  );
}

const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); ro.disconnect(); return; }
  if (userPaused || hovering || focusIn || active !== -1 || !visible || document.hidden || reduce.matches) return;
  swapOne();
}, 2800);

const io = new IntersectionObserver((es) => { visible = es[es.length - 1].isIntersecting; });
io.observe(grid);
const ro = new ResizeObserver(() => { if (active !== -1) place(active); });
ro.observe(root);

pauseBtn.addEventListener('click', () => {
  userPaused = !userPaused;
  pauseBtn.setAttribute('aria-pressed', String(userPaused));
  pauseBtn.querySelector('span').textContent = userPaused ? 'Resume rotation' : 'Pause rotation';
  status.textContent = userPaused ? 'Rotation paused · 12 of 18 featured customers' : 'Showing 12 of 18 featured customers';
});
if (reduce.matches) status.textContent = '12 of 18 featured customers';

