.bks-units {
  /* re-theme with these four (the five group hues follow below) */
  --bks-units-bg: oklch(17.5% 0.009 70);
  --bks-units-ink: oklch(93.5% 0.014 85);
  --bks-units-accent: oklch(79% 0.135 72);
  --bks-units-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --bks-units-c1: var(--bks-units-accent);
  --bks-units-c2: oklch(70% 0.15 34);
  --bks-units-c3: oklch(77% 0.1 152);
  --bks-units-c4: oklch(73% 0.085 236);
  --bks-units-c5: oklch(69% 0.11 340);
  --bks-units-dot: color-mix(in oklch, var(--bks-units-ink) 82%, var(--bks-units-bg));
  --bks-units-muted: color-mix(in oklch, var(--bks-units-ink) 56%, var(--bks-units-bg));
  --bks-units-line: color-mix(in oklch, var(--bks-units-ink) 11%, var(--bks-units-bg));
  --bks-units-raise: color-mix(in oklch, var(--bks-units-ink) 5%, var(--bks-units-bg));
  --bks-units-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(70% 60% at 30% 70%, color-mix(in oklch, var(--bks-units-accent) 6%, transparent), transparent 70%),
    var(--bks-units-bg);
  color: var(--bks-units-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, li) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; }
}

.bks-units-in {
  padding: clamp(36px, 6.5cqi, 84px) clamp(16px, 5cqi, 64px);
  display: grid; gap: clamp(22px, 3.5cqi, 40px);
}

.bks-units-head {
  display: grid; gap: 14px 40px;
  grid-template-areas: "kicker" "title" "tabs";
}
.bks-units-kicker {
  grid-area: kicker;
  display: flex; align-items: center; gap: 9px;
  font: 500 11.5px/1 var(--bks-units-mono); letter-spacing: .1em; text-transform: uppercase;
  color: var(--bks-units-accent);
  & svg { width: 14px; height: 14px; fill: currentColor; }
}
.bks-units-title {
  grid-area: title;
  font-size: clamp(28px, 3.4cqi + 14px, 50px); font-weight: 650;
  line-height: 1.04; letter-spacing: -.035em;
  text-wrap: balance;
  max-width: 20ch;
  & span { color: var(--bks-units-muted); font-weight: 450; }
}

.bks-units-tabs {
  grid-area: tabs;
  display: grid; grid-template-columns: repeat(4, auto); justify-content: start; gap: 6px;
  align-self: end;
}
.bks-units-tab {
  height: 34px; padding: 0 clamp(9px, 2.4cqi, 14px);
  border: 1px solid var(--bks-units-line); border-radius: 8px;
  background: transparent;
  font: 500 12.5px/1 var(--bks-units-mono); letter-spacing: .02em;
  color: var(--bks-units-muted);
  cursor: pointer;
  transition: color .25s var(--bks-units-out), background-color .25s var(--bks-units-out), border-color .25s;
  &:hover { color: var(--bks-units-ink); border-color: color-mix(in oklch, var(--bks-units-ink) 24%, var(--bks-units-bg)); }
  &[aria-selected="true"] { background: var(--bks-units-ink); color: var(--bks-units-bg); border-color: var(--bks-units-ink); }
  &:focus-visible { outline: 2px solid var(--bks-units-accent); outline-offset: 2px; }
}

.bks-units-body {
  display: grid; gap: 24px;
  grid-template-columns: minmax(0, 1fr);
}
.bks-units-stage {
  position: relative;
  height: 500px;
}
.bks-units-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.bks-units-tip {
  position: absolute; left: 0; top: 0; z-index: 2;
  display: grid; gap: 1px;
  padding: 7px 10px 8px;
  border-radius: 8px;
  background: var(--bks-units-ink); color: var(--bks-units-bg);
  font-size: 12px; line-height: 1.3; white-space: nowrap;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  opacity: 0; scale: .94;
  transform-origin: 50% 100%;
  transition: opacity .16s var(--bks-units-out), scale .3s var(--bks-units-out), translate .32s var(--bks-units-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & span { color: color-mix(in oklch, var(--bks-units-bg) 70%, var(--bks-units-ink)); }
}

.bks-units-side { display: grid; gap: 14px; align-content: start; }
.bks-units-legend { display: grid; gap: 2px; }
.bks-units-key {
  width: 100%;
  display: grid; grid-template-columns: 10px minmax(0, 1fr) auto 52px; align-items: center; gap: 10px;
  padding: 8px 10px; margin-inline: -10px; width: calc(100% + 20px);
  border: 0; border-radius: 8px;
  background: transparent; text-align: left;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background-color .2s var(--bks-units-out), opacity .25s var(--bks-units-out);
  & i { width: 10px; height: 10px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 0 var(--c); transition: box-shadow .3s var(--bks-units-out); }
  & .bks-units-kn { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .bks-units-kv { font-weight: 600; }
  & .bks-units-kp { color: var(--bks-units-muted); text-align: right; font-family: var(--bks-units-mono); font-size: 12px; }
  &:hover, &:focus-visible, &.is-hl, &[aria-pressed="true"] { background: var(--bks-units-raise); }
  &[aria-pressed="true"] i { box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 35%, transparent); }
  &:focus-visible { outline: 2px solid var(--bks-units-accent); outline-offset: -2px; }
}
.bks-units-legend:has(.bks-units-key[aria-pressed="true"]) .bks-units-key:not([aria-pressed="true"]) { opacity: .5; }

.bks-units-total {
  display: grid; grid-template-columns: minmax(0, 1fr) auto 52px; gap: 10px;
  padding-top: 12px; border-top: 1px solid var(--bks-units-line);
  font-size: 13.5px; font-variant-numeric: tabular-nums;
  & span:first-child { color: var(--bks-units-muted); padding-left: 20px; }
  & span:last-child { color: var(--bks-units-muted); text-align: right; font-family: var(--bks-units-mono); font-size: 12px; }
}
.bks-units-note { font-size: 12.5px; color: var(--bks-units-muted); text-wrap: pretty; max-width: 40ch; }

@container (min-width: 560px) {
  .bks-units-stage { height: 440px; }
  .bks-units-side { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 32px; }
  .bks-units-legend, .bks-units-total { grid-column: 1; }
  .bks-units-note { grid-column: 2; grid-row: 1; align-self: end; }
}
@container (min-width: 900px) {
  .bks-units-head {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "kicker kicker" "title tabs";
  }
  .bks-units-body { grid-template-columns: minmax(0, 1fr) 270px; gap: 40px; }
  .bks-units-side { grid-template-columns: minmax(0, 1fr); align-content: end; padding-bottom: 6px; }
  .bks-units-legend, .bks-units-total, .bks-units-note { grid-column: 1; grid-row: auto; }
}

@media (prefers-reduced-motion: reduce) {
  .bks-units {
    & .bks-units-tip { transition: opacity .12s linear; scale: 1; }
    & .bks-units-key, & .bks-units-tab { transition: none; }
  }
}

