// 3,219 dots × 20 teams = 64,380. Every facet's counts sum to the same 3,219.
const PER = 20;
const FACETS = {
  all: { label: 'everyone', groups: [['All workspaces', 'All teams', 3219]] },
  region: { label: 'region', groups: [['North America', 'N. America', 1159], ['Europe', 'Europe', 1051], ['Asia-Pacific', 'Asia-Pacific', 706], ['Latin America', 'Latin America', 193], ['Middle East & Africa', 'Mid. East & Africa', 110]] },
  plan: { label: 'plan', groups: [['Free', 'Free', 1770], ['Team', 'Team', 1031], ['Business', 'Business', 322], ['Enterprise', 'Enterprise', 96]] },
  size: { label: 'team size', groups: [['1–10 people', '1–10', 1931], ['11–50 people', '11–50', 869], ['51–250 people', '51–250', 290], ['251+ people', '251+', 129]] }
};
const N = 3219;
const TAU = Math.PI * 2;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const nf = new Intl.NumberFormat('en-US');

const stage = root.querySelector('.bks-units-stage');
const cv = root.querySelector('.bks-units-cv');
const ctx = cv.getContext('2d');
const tip = root.querySelector('.bks-units-tip');
const legend = root.querySelector('.bks-units-legend');
const tabs = [...root.querySelectorAll('.bks-units-tab')];
const panel = root.querySelector('.bks-units-body');

const uid = Math.random().toString(36).slice(2, 8);
panel.id = 'bks-units-panel-' + uid;
tabs.forEach((t, i) => { t.id = 'bks-units-tab-' + uid + '-' + i; t.setAttribute('aria-controls', panel.id); });

/* ---------- deterministic population ---------- */
let seed = 20260930;
const rnd = () => { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const exact = (groups) => groups.flatMap(([, , c], g) => Array(c).fill(g));
const shuffle = (a) => { for (let i = a.length - 1; i > 0; i--) { const j = (rnd() * (i + 1)) | 0; [a[i], a[j]] = [a[j], a[i]]; } return a; };
const ATTR = { all: new Uint8Array(N) };
ATTR.region = Uint8Array.from(shuffle(exact(FACETS.region.groups)));
ATTR.plan = Uint8Array.from(shuffle(exact(FACETS.plan.groups)));
// team size correlates with plan (enterprise teams are big), so Plan → Team size reads true
{
  const order = [...Array(N).keys()].sort((a, b) => (ATTR.plan[a] + rnd() * 1.7) - (ATTR.plan[b] + rnd() * 1.7));
  const sizes = exact(FACETS.size.groups);
  ATTR.size = new Uint8Array(N);
  order.forEach((i, k) => { ATTR.size[i] = sizes[k]; });
}

/* ---------- palette, read from the root's custom properties ---------- */
let COLORS = [];
function readColors() {
  const probe = document.createElement('i');
  probe.style.display = 'none';
  root.appendChild(probe);
  COLORS = ['--bks-units-dot', '--bks-units-c1', '--bks-units-c2', '--bks-units-c3', '--bks-units-c4', '--bks-units-c5', '--bks-units-muted', '--bks-units-ink'].map((v) => {
    probe.style.color = 'var(' + v + ')';
    return getComputedStyle(probe).color;
  });
  probe.remove();
}
readColors();

/* ---------- state ---------- */
const px = new Float32Array(N), py = new Float32Array(N);
const fx = new Float32Array(N), fy = new Float32Array(N);
const tx = new Float32Array(N), ty = new Float32Array(N);
const dl = new Float32Array(N);
const c0 = new Uint8Array(N), c1 = new Uint8Array(N), pc = new Uint8Array(N);
let facet = 'all', W = 0, H = 0, dpr = 1;
let rFrom = 0, rTo = 0, rad = 0;
let rects = [], labels = [];
let clock = 0, last = 0, t0 = 0, raf = 0, started = false, visible = false;
let hl = -1, hlShown = -1, hlA = 0, pinned = -1;

// damped spring step response (ζ 0.68, ω 11 rad/s): ~0.6 s to settle
const Z = 0.68, OM = 11, WD = OM * Math.sqrt(1 - Z * Z), SETTLE = 0.75;
const spring = (t) => 1 - Math.exp(-Z * OM * t) * (Math.cos(WD * t) + (Z * OM / WD) * Math.sin(WD * t));

/* ---------- layouts ---------- */
function layout(f) {
  const out = { x: new Float32Array(N), y: new Float32Array(N), r: 0, rects: [], labels: [], delay: new Float32Array(N), color: new Uint8Array(N) };
  if (f === 'all') {
    // Vogel sunflower: index order spirals outward, so later layouts drain from the centre
    const R = Math.min(W, H) / 2 - 6, cx = W / 2, cy = H / 2, ga = Math.PI * (3 - Math.sqrt(5));
    for (let i = 0; i < N; i++) {
      const r = R * Math.sqrt((i + 0.5) / N), a = i * ga;
      out.x[i] = cx + r * Math.cos(a); out.y[i] = cy + r * Math.sin(a);
      out.delay[i] = (i / N) * 420; out.color[i] = 0;
    }
    out.r = R * Math.sqrt(Math.PI / N) * 0.36;
    out.rects = [{ x: cx - R, y: cy - R, w: 2 * R, h: 2 * R, g: 0, ax: cx, ay: cy - R }];
    return out;
  }
  const groups = FACETS[f].groups, G = groups.length, attr = ATTR[f];
  const members = groups.map(() => []);
  for (let i = 0; i < N; i++) members[attr[i]].push(i);
  const vertical = W >= 520;
  if (vertical) {
    const top = 26, bottom = 40, gap = Math.max(14, W * 0.028);
    const colW = (W - gap * (G - 1)) / G, availH = H - top - bottom;
    const maxC = Math.max(...groups.map((g) => g[2]));
    let p = 16;
    while (p > 2 && Math.ceil(maxC / Math.floor(colW / p)) * p > availH) p -= 0.1;
    const cols = Math.floor(colW / p), base = H - bottom;
    groups.forEach(([, short, cnt], g) => {
      const colX = g * (colW + gap), x0 = colX + (colW - cols * p) / 2;
      const rows = Math.ceil(cnt / cols);
      members[g].forEach((i, k) => {
        out.x[i] = x0 + (k % cols) * p + p / 2;
        out.y[i] = base - Math.floor(k / cols) * p - p / 2;
        out.delay[i] = (k / cnt) * 380 + g * 70 + rnd() * 60;
        out.color[i] = g + 1;
      });
      const topY = base - rows * p;
      out.rects.push({ x: colX, y: 0, w: colW, h: H, g, ax: colX + colW / 2, ay: topY - 26 });
      out.labels.push({ t: short, x: colX + colW / 2, y: base + 18, align: 'center', kind: 'name', g });
      out.labels.push({ t: nf.format(cnt * PER), x: colX + colW / 2, y: topY - 9, align: 'center', kind: 'num', g });
    });
    out.r = p * 0.36;
  } else {
    const head = 22, gap = 12;
    let p = 12, cols = 0, total = 0;
    do {
      p -= 0.1; cols = Math.floor(W / p);
      total = groups.reduce((s, g) => s + head + Math.ceil(g[2] / cols) * p, 0) + gap * (G - 1);
    } while (p > 2 && total > H);
    let y = 0;
    const x0 = (W - cols * p) / 2;
    groups.forEach(([, short, cnt], g) => {
      const rows = Math.ceil(cnt / cols);
      out.labels.push({ t: short, x: x0, y: y + 13, align: 'left', kind: 'name', g });
      out.labels.push({ t: nf.format(cnt * PER), x: W - x0, y: y + 13, align: 'right', kind: 'num', g });
      const y0 = y + head;
      members[g].forEach((i, k) => {
        out.x[i] = x0 + (k % cols) * p + p / 2;
        out.y[i] = y0 + Math.floor(k / cols) * p + p / 2;
        out.delay[i] = (k / cnt) * 380 + g * 70 + rnd() * 60;
        out.color[i] = g + 1;
      });
      out.rects.push({ x: 0, y, w: W, h: head + rows * p, g, ax: W / 2, ay: y0 - 4 });
      y += head + rows * p + gap;
    });
    out.r = p * 0.36;
  }
  return out;
}

function go(f, from) {
  const L = layout(f);
  facet = f;
  rects = L.rects; labels = L.labels;
  for (let i = 0; i < N; i++) {
    fx[i] = from ? from.x : px[i]; fy[i] = from ? from.y : py[i];
    tx[i] = L.x[i]; ty[i] = L.y[i];
    dl[i] = L.delay[i];
    c0[i] = pc[i]; c1[i] = L.color[i];
  }
  rFrom = from ? 0 : rad; rTo = L.r;
  t0 = clock;
  if (reduce.matches) { t0 = clock - 1e6; }
  kick();
}

function snap() {
  const L = layout(facet);
  rects = L.rects; labels = L.labels;
  for (let i = 0; i < N; i++) { fx[i] = tx[i] = px[i] = L.x[i]; fy[i] = ty[i] = py[i] = L.y[i]; c0[i] = c1[i] = pc[i] = L.color[i]; }
  rFrom = rTo = rad = L.r;
  t0 = clock - 1e6;
  draw(1);
}

/* ---------- frame loop: runs only while something moves ---------- */
function kick() {
  if (!raf && visible && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(frame); }
}
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || document.hidden) return;
  clock += Math.min(50, now - last); last = now;
  const T = clock - t0;
  let moving = false;
  for (let i = 0; i < N; i++) {
    const lt = (T - dl[i]) / 1000;
    if (lt <= 0) { px[i] = fx[i]; py[i] = fy[i]; pc[i] = c0[i]; moving = true; continue; }
    const e = lt >= SETTLE ? 1 : spring(lt);
    if (lt < SETTLE) moving = true;
    px[i] = fx[i] + (tx[i] - fx[i]) * e; py[i] = fy[i] + (ty[i] - fy[i]) * e; pc[i] = c1[i];
  }
  const rp = Math.min(1, Math.max(0, T / 700));
  rad = rFrom + (rTo - rFrom) * (1 - Math.pow(1 - rp, 3));
  // highlight fade
  const want = hl >= 0 ? 1 : 0;
  if (hl >= 0) hlShown = hl;
  hlA += (want - hlA) * 0.25;
  if (Math.abs(want - hlA) < 0.01) hlA = want; else moving = true;
  const la = Math.min(1, Math.max(0, (T - 450) / 450));
  if (la < 1) moving = true;
  draw(la);
  if (moving) raf = requestAnimationFrame(frame);
}

function draw(labelAlpha) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const r = Math.max(0.5, rad), dimA = 1 - hlA * 0.82, grp = ATTR[facet];
  for (let c = 0; c < 6; c++) {
    for (let pass = 0; pass < 2; pass++) {
      if (pass === 1 && hlA === 0) continue;
      ctx.globalAlpha = pass ? dimA : 1;
      ctx.fillStyle = COLORS[c];
      ctx.beginPath();
      let any = false;
      for (let i = 0; i < N; i++) {
        if (pc[i] !== c) continue;
        const dim = hlA > 0 && grp[i] !== hlShown;
        if (dim !== (pass === 1)) continue;
        ctx.moveTo(px[i] + r, py[i]);
        ctx.arc(px[i], py[i], r, 0, TAU);
        any = true;
      }
      if (any) ctx.fill();
    }
  }
  if (labelAlpha > 0 && labels.length) {
    labels.forEach((l) => {
      const dim = hlA > 0 && l.g !== hlShown;
      ctx.globalAlpha = labelAlpha * (dim ? dimA : 1);
      ctx.fillStyle = l.kind === 'num' ? COLORS[7] : COLORS[6];
      ctx.font = l.kind === 'num' ? '600 12px ui-monospace, Menlo, monospace' : '500 12px system-ui, -apple-system, sans-serif';
      ctx.textAlign = l.align;
      ctx.fillText(l.t, l.x, l.y);
    });
  }
  ctx.globalAlpha = 1;
}

/* ---------- legend + tooltip ---------- */
function renderLegend() {
  const groups = FACETS[facet].groups;
  legend.innerHTML = groups.map(([name, , cnt], g) =>
    '<li><button class="bks-units-key" type="button" aria-pressed="false" tabindex="' + (g ? -1 : 0) + '" data-g="' + g + '" style="--c:var(--bks-units-' + (facet === 'all' ? 'dot' : 'c' + (g + 1)) + ')">' +
    '<i></i><span class="bks-units-kn">' + name + '</span><span class="bks-units-kv">' + nf.format(cnt * PER) + '</span>' +
    '<span class="bks-units-kp">' + (cnt / N * 100).toFixed(1) + '%</span></button></li>').join('');
  cv.setAttribute('aria-label', facet === 'all'
    ? '3,219 dots, one per twenty teams: 64,380 teams in all'
    : 'Dots grouped by ' + FACETS[facet].label + ': ' + groups.map(([n, , c]) => n + ' ' + nf.format(c * PER) + ' teams').join(', '));
}
function showTip(g) {
  const rc = rects.find((r) => r.g === g);
  if (g < 0 || !rc) { tip.classList.remove('is-on'); return; }
  const [name, , cnt] = FACETS[facet].groups[g];
  tip.querySelector('b').textContent = name;
  tip.querySelector('span').textContent = nf.format(cnt * PER) + ' teams · ' + (cnt / N * 100).toFixed(1) + '%';
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const x = Math.max(0, Math.min(W - tw, rc.ax - tw / 2));
  const y = Math.max(0, rc.ay - th - 6);
  if (!tip.classList.contains('is-on')) { tip.style.transition = 'none'; tip.style.translate = x + 'px ' + y + 'px'; void tip.offsetWidth; tip.style.transition = ''; }
  tip.style.translate = x + 'px ' + y + 'px';
  tip.classList.add('is-on');
}
function setHL(g) {
  if (g === hl) return;
  hl = g;
  legend.querySelectorAll('.bks-units-key').forEach((k) => k.classList.toggle('is-hl', +k.dataset.g === g));
  if (facet === 'all' && g >= 0) hl = -1;
  showTip(g);
  kick();
  if (!raf) draw(1);
}

cv.addEventListener('pointermove', (e) => {
  if (pinned >= 0) return;
  const b = cv.getBoundingClientRect(), x = e.clientX - b.left, y = e.clientY - b.top;
  const hit = rects.find((r) => x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h);
  setHL(hit ? hit.g : -1);
});
cv.addEventListener('pointerleave', () => { if (pinned < 0) setHL(-1); });
cv.addEventListener('click', () => {
  if (hl < 0 && facet !== 'all') return;
  const btn = legend.querySelector('[data-g="' + (hl < 0 ? 0 : hl) + '"]');
  if (btn) btn.click();
});

legend.addEventListener('pointerover', (e) => { const k = e.target.closest('.bks-units-key'); if (k && pinned < 0) setHL(+k.dataset.g); });
legend.addEventListener('pointerleave', () => { if (pinned < 0) setHL(-1); });
legend.addEventListener('focusin', (e) => {
  const k = e.target.closest('.bks-units-key');
  if (!k) return;
  legend.querySelectorAll('.bks-units-key').forEach((x) => { x.tabIndex = x === k ? 0 : -1; });
  if (pinned < 0) setHL(+k.dataset.g);
});
legend.addEventListener('focusout', (e) => { if (!legend.contains(e.relatedTarget) && pinned < 0) setHL(-1); });
legend.addEventListener('click', (e) => {
  const k = e.target.closest('.bks-units-key');
  if (!k) return;
  const g = +k.dataset.g, on = pinned !== g;
  pinned = on ? g : -1;
  legend.querySelectorAll('.bks-units-key').forEach((x) => x.setAttribute('aria-pressed', String(on && x === k)));
  hl = -2; setHL(on ? g : -1);
});
legend.addEventListener('keydown', (e) => {
  const keys = [...legend.querySelectorAll('.bks-units-key')];
  const i = keys.indexOf(document.activeElement);
  if (i < 0) return;
  let j = null;
  if (e.key === 'ArrowDown') j = Math.min(keys.length - 1, i + 1);
  else if (e.key === 'ArrowUp') j = Math.max(0, i - 1);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = keys.length - 1;
  else if (e.key === 'Escape' && pinned >= 0) { e.preventDefault(); keys[pinned].click(); return; }
  if (j === null) return;
  e.preventDefault();
  keys[j].focus();
});

/* ---------- tabs ---------- */
function select(tab, focus) {
  tabs.forEach((t) => { const on = t === tab; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; });
  panel.setAttribute('aria-labelledby', tab.id);
  if (focus) tab.focus();
  const f = tab.dataset.f;
  if (f === facet) return;
  pinned = -1; hl = -1; hlA = 0; tip.classList.remove('is-on');
  if (!started) { facet = f; renderLegend(); return; }
  go(f);
  renderLegend();
}
tabs.forEach((t) => t.addEventListener('click', () => select(t)));
root.querySelector('.bks-units-tabs').addEventListener('keydown', (e) => {
  const i = tabs.indexOf(document.activeElement);
  if (i < 0) return;
  const n = tabs.length;
  const j = e.key === 'ArrowRight' ? (i + 1) % n : e.key === 'ArrowLeft' ? (i - 1 + n) % n : e.key === 'Home' ? 0 : e.key === 'End' ? n - 1 : -1;
  if (j < 0) return;
  e.preventDefault();
  select(tabs[j], true);
});

/* ---------- sizing, visibility ---------- */
function resize() {
  const b = stage.getBoundingClientRect();
  if (!b.width || !b.height) return;
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = b.width; H = b.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  if (started) {
    if (raf) { cancelAnimationFrame(raf); raf = 0; }
    snap();
    if (hl >= 0) showTip(hl);
  }
}
function cleanup() { ro.disconnect(); io.disconnect(); document.removeEventListener('visibilitychange', onVis); }
const ro = new ResizeObserver(() => { if (root.isConnected) resize(); else cleanup(); });
ro.observe(stage);

function start() {
  started = true;
  resize();
  if (reduce.matches) { snap(); return; }
  const L = layout(facet);
  for (let i = 0; i < N; i++) { px[i] = W / 2; py[i] = H / 2; pc[i] = L.color[i]; }
  go(facet, { x: W / 2, y: H / 2 });
}

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { cleanup(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible && !started) start();
  else if (visible) kick();
}, { threshold: 0.2 });
io.observe(stage);

const onVis = () => {
  if (!root.isConnected) { cleanup(); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);

renderLegend();

