.bks-trust {
  /* re-theme with these four */
  --bks-trust-paper: oklch(98.4% 0.003 250);
  --bks-trust-ink: oklch(19% 0.012 260);
  --bks-trust-ok: oklch(65% 0.14 152);
  --bks-trust-bad: oklch(58% 0.2 28);

  --bks-trust-warn: oklch(79% 0.15 78);
  --bks-trust-muted: color-mix(in oklch, var(--bks-trust-ink) 58%, var(--bks-trust-paper));
  --bks-trust-rule: color-mix(in oklch, var(--bks-trust-ink) 13%, var(--bks-trust-paper));
  --bks-trust-raise: color-mix(in oklch, var(--bks-trust-ink) 3%, var(--bks-trust-paper));
  --bks-trust-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bks-trust-out: cubic-bezier(.16, 1, .3, 1);
  --bks-trust-spring: linear(0, 0.042, 0.145, 0.283, 0.433, 0.579, 0.712, 0.826, 0.917, 0.985, 1.033, 1.063, 1.079, 1.084, 1.08, 1.071, 1.06, 1.047, 1.035, 1.024, 1.015, 1.007, 1.001, 0.997, 0.995, 0.993, 0.993, 0.993, 0.994, 0.995, 0.996, 0.997, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-trust-paper);
  color: var(--bks-trust-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dt, dd, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; }
}
.bks-trust-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.bks-trust-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bks-trust-in {
  /* how many days the strip shows; a container query widens it, the JS reads it back */
  --bks-trust-window: 45;
  padding: clamp(36px, 6.5cqi, 88px) clamp(16px, 5cqi, 64px);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "seals" "detail" "up";
  gap: clamp(24px, 4cqi, 48px) 48px;
}

/* ---------- header ---------- */
.bks-trust-head { grid-area: head; display: grid; gap: 14px; max-width: 760px; }
.bks-trust-kicker {
  display: flex; align-items: center; gap: 8px;
  font: 600 11.5px/1 var(--bks-trust-mono); letter-spacing: .1em; text-transform: uppercase;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
}
.bks-trust-title {
  font-size: clamp(32px, 4.4cqi + 12px, 64px); font-weight: 750;
  line-height: .98; letter-spacing: -.045em;
  text-wrap: balance;
}
.bks-trust-lede { color: var(--bks-trust-muted); max-width: 54ch; font-size: clamp(15px, .35cqi + 13.5px, 17px); text-wrap: pretty; }

/* ---------- seals ---------- */
.bks-trust-seals {
  grid-area: seals;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px clamp(10px, 2.5cqi, 28px);
  padding-block: 4px;
}
.bks-trust-seal {
  position: relative;
  justify-self: center;
  width: 100%; max-width: 148px; aspect-ratio: 1;
  padding: 0; border: 0; border-radius: 50%;
  background: none; cursor: pointer;
  & svg { display: block; width: 100%; height: 100%; overflow: visible; transition: scale .5s var(--bks-trust-spring); }
  &:active svg { scale: .95; }
  &:focus-visible { outline: 2px solid var(--bks-trust-ink); outline-offset: 4px; }
}
.bks-trust-disc { fill: transparent; transition: fill .4s var(--bks-trust-out); }
.bks-trust-o { fill: none; stroke: var(--bks-trust-ink); stroke-width: 1.4; }
.bks-trust-i { fill: none; stroke: var(--bks-trust-ink); stroke-width: 1; stroke-dasharray: .6 2.4; stroke-linecap: round; }
.bks-trust-ring {
  transform-origin: 60px 60px;
  transition: rotate 1.4s var(--bks-trust-spring);
  & text { font: 600 7.4px var(--bks-trust-mono); fill: var(--bks-trust-ink); }
}
.bks-trust-big { font: 800 20px system-ui, -apple-system, sans-serif; letter-spacing: -.6px; fill: var(--bks-trust-ink); }
.bks-trust-sub { font: 600 7.6px var(--bks-trust-mono); letter-spacing: 1.4px; fill: var(--bks-trust-muted); }
.bks-trust-seal :is(.bks-trust-o, .bks-trust-i) { transition: stroke .4s var(--bks-trust-out); }
.bks-trust-seal :is(.bks-trust-ring text, .bks-trust-big, .bks-trust-sub) { transition: fill .4s var(--bks-trust-out); }
.bks-trust-seal:hover .bks-trust-ring { rotate: 28deg; }
.bks-trust-seal[aria-selected="true"] {
  & .bks-trust-disc { fill: var(--bks-trust-ink); }
  & .bks-trust-o, & .bks-trust-i { stroke: var(--bks-trust-paper); }
  & .bks-trust-ring text, & .bks-trust-big { fill: var(--bks-trust-paper); }
  & .bks-trust-sub { fill: color-mix(in oklch, var(--bks-trust-paper) 70%, var(--bks-trust-ink)); }
  & .bks-trust-ring { rotate: 180deg; }
  &:hover .bks-trust-ring { rotate: 208deg; }
}

/* ---------- seal detail ---------- */
.bks-trust-detail {
  grid-area: detail;
  align-self: start;
  border-top: 2px solid var(--bks-trust-ink);
  padding-top: 16px;
  display: grid; gap: 14px;
}
.bks-trust-dname { font-size: 20px; font-weight: 700; letter-spacing: -.02em; }
.bks-trust-drows {
  display: grid; gap: 0;
  & div { display: grid; grid-template-columns: minmax(0, 1fr); gap: 2px; padding: 10px 0; border-top: 1px solid var(--bks-trust-rule); }
  & dt { font: 600 10.5px/1.4 var(--bks-trust-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bks-trust-muted); }
  & dd { font-size: 14.5px; text-wrap: pretty; }
}

/* ---------- uptime ---------- */
.bks-trust-up {
  grid-area: up;
  position: relative;
  align-self: start;
  border: 1px solid var(--bks-trust-rule);
  background: var(--bks-trust-raise);
  padding: clamp(18px, 2.6cqi, 28px);
  display: grid; gap: 14px;
}
.bks-trust-uphead {
  display: grid; gap: 4px 20px;
  grid-template-areas: "label" "big" "svc";
}
.bks-trust-uplabel { grid-area: label; font: 600 11px/1.4 var(--bks-trust-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bks-trust-muted); }
.bks-trust-upbig {
  grid-area: big;
  font-size: clamp(44px, 4cqi + 24px, 64px); font-weight: 750; line-height: 1; letter-spacing: -.05em;
  font-variant-numeric: tabular-nums;
  & small { font-size: .45em; font-weight: 500; letter-spacing: 0; margin-left: 3px; color: var(--bks-trust-muted); }
}
.bks-trust-svc {
  grid-area: svc;
  display: flex; flex-wrap: wrap; gap: 4px 16px; margin-top: 10px;
  & label { display: inline-flex; align-items: center; gap: 6px; font-size: 13.5px; cursor: pointer; }
  & input { margin: 0; width: 15px; height: 15px; accent-color: var(--bks-trust-ink); cursor: pointer; }
  & input:focus-visible { outline: 2px solid var(--bks-trust-ink); outline-offset: 2px; }
  & label:has(input:checked) { font-weight: 650; }
}

.bks-trust-days {
  display: grid;
  grid-template-columns: repeat(var(--bks-trust-window), minmax(0, 1fr));
  gap: 2px; height: 44px; margin-top: 6px;
}
.bks-trust-day {
  height: 100%; min-width: 0;
  padding: 0; border: 0; border-radius: 1.5px;
  background: var(--bks-trust-ok);
  cursor: default;
  transform-origin: 50% 100%;
  transition:
    background-color .45s var(--bks-trust-out) calc(max(0, var(--i) - 90 + var(--bks-trust-window)) * 5ms),
    scale .3s var(--bks-trust-spring),
    opacity .25s var(--bks-trust-out);
  &[data-s="minor"] { background: var(--bks-trust-warn); }
  &[data-s="major"] { background: var(--bks-trust-bad); }
  &:hover, &:focus-visible { scale: 1 1.16; }
  &:focus-visible { outline: 2px solid var(--bks-trust-ink); outline-offset: 2px; }
  &:nth-child(-n+45) { display: none; }
}
.bks-trust-days:has(.bks-trust-day:is(:hover, :focus-visible)) .bks-trust-day:not(:hover, :focus-visible) { opacity: .4; }

.bks-trust-axis {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  font: 500 11px/1 var(--bks-trust-mono); color: var(--bks-trust-muted);
}
.bks-trust-legend {
  display: none; align-items: center; gap: 6px;
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--bks-trust-ok); margin-left: 8px; }
  & i[data-s="minor"] { background: var(--bks-trust-warn); }
  & i[data-s="major"] { background: var(--bks-trust-bad); }
}

.bks-trust-tip {
  position: absolute; left: 0; top: 0; z-index: 2;
  width: max-content; max-width: min(260px, calc(100% - 24px));
  display: grid; gap: 2px;
  padding: 9px 11px 10px;
  background: var(--bks-trust-ink); color: var(--bks-trust-paper);
  font-size: 12px; line-height: 1.35;
  pointer-events: none;
  opacity: 0; translate: 0 -4px;
  transition: opacity .15s var(--bks-trust-out), translate .3s var(--bks-trust-out);
  &.is-on { opacity: 1; translate: 0 0; }
  & b { font-weight: 650; font-variant-numeric: tabular-nums; }
  & span { font-variant-numeric: tabular-nums; }
  & em { font-style: normal; color: color-mix(in oklch, var(--bks-trust-paper) 68%, var(--bks-trust-ink)); text-wrap: pretty; }
  & em:empty { display: none; }
}

.bks-trust-stats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--bks-trust-rule); padding-top: 14px; margin-top: 4px;
  & dt { font: 600 10.5px/1.4 var(--bks-trust-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bks-trust-muted); }
  & dd { font-size: 19px; font-weight: 650; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
}

/* ---------- container breakpoints ---------- */
@container (min-width: 560px) {
  .bks-trust-in { --bks-trust-window: 90; }
  .bks-trust-day:nth-child(-n+45) { display: block; }
  .bks-trust-legend { display: inline-flex; }
  .bks-trust-drows div { grid-template-columns: 170px minmax(0, 1fr); gap: 16px; }
  .bks-trust-uphead { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "label label" "big svc"; align-items: end; }
  .bks-trust-svc { justify-content: flex-end; margin: 0 0 8px; }
}
@container (min-width: 700px) {
  .bks-trust-seals { grid-template-columns: repeat(6, minmax(0, 1fr)); }
}
@container (min-width: 980px) {
  .bks-trust-in {
    grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr);
    grid-template-areas: "head head" "seals seals" "detail up";
  }
  .bks-trust-drows div { grid-template-columns: 150px minmax(0, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .bks-trust {
    & .bks-trust-ring, & .bks-trust-seal svg, & .bks-trust-day, & .bks-trust-tip { transition: none; }
    & .bks-trust-seal:hover .bks-trust-ring { rotate: 0deg; }
    & .bks-trust-seal[aria-selected="true"] .bks-trust-ring { rotate: 0deg; }
    & .bks-trust-day:hover, & .bks-trust-day:focus-visible { scale: 1; }
  }
}

