// Every figure on the uptime card is derived from these incident minutes.
const D = {"seals": [{"name": "SOC 2 Type II", "rows": [["Report period", "1 Jul 2025 – 30 Jun 2026"], ["Auditor", "Brannock & Wills LLP"], ["Exceptions", "None noted"], ["Scope", "Control plane, managed databases, backups and support tooling"]]}, {"name": "ISO/IEC 27001:2022", "rows": [["Certificate", "OC-27K-0417, valid to 14 Mar 2028"], ["Certification body", "Nordmark Assurance"], ["Surveillance audit", "Mar 2026, no nonconformities"], ["Scope", "Engineering, operations and support in three offices"]]}, {"name": "HIPAA", "rows": [["Business associate agreement", "Business and Enterprise plans"], ["Assessment", "Third-party review, May 2026"], ["Encryption", "AES-256 at rest, TLS 1.3 in transit"], ["Isolation", "Dedicated clusters, optional customer-held keys"]]}, {"name": "GDPR", "rows": [["Data residency", "Frankfurt and Dublin regions"], ["Agreement", "Standard DPA with SCCs"], ["Sub-processors", "7, changes announced 30 days ahead"], ["Data protection officer", "Appointed, based in Dublin"]]}, {"name": "PCI DSS v4.0", "rows": [["Level", "Service provider, Level 1"], ["Attestation", "AoC dated 12 Jun 2026"], ["Assessor", "Halloran Security"], ["Scope", "Billing only: card data never reaches your databases"]]}, {"name": "Penetration test 2026", "rows": [["Tester", "Ironbark Labs"], ["Window", "2–20 Mar 2026"], ["Findings", "0 critical · 0 high · 2 medium"], ["Remediation", "Both mediums fixed in 9 days; retest passed"]]}], "services": [{"name": "API", "inc": [[16, 6, "Elevated 502s from one load balancer in eu-central"], [42, 10, "Connection-pool exhaustion after a config push; rolled back"], [68, 1, "DNS failover during planned provider maintenance"]]}, {"name": "Dashboard", "inc": [[30, 24, "Static assets failed to load for some EU users"], [80, 3, "Sign-in redirect loop after a session-cookie change"]]}, {"name": "Webhooks", "inc": [[25, 41, "Delivery delayed; queued events arrived in order, none lost"], [42, 4, "Retries backed off longer than configured"]]}, {"name": "Backups", "inc": []}], "start": [2026, 6, 3], "days": 90};
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 8);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

// one shared arc for every ring of text; give this copy its own id
const arc = root.querySelector('.bks-trust-defs path');
arc.id = 'bks-trust-arc-' + uid;
root.querySelectorAll('textPath').forEach((t) => t.setAttribute('href', '#' + arc.id));

/* ---------- seals: a tablist driving one detail panel ---------- */
const seals = [...root.querySelectorAll('.bks-trust-seal')];
const detail = root.querySelector('.bks-trust-detail');
const dName = detail.querySelector('.bks-trust-dname');
const dRows = detail.querySelector('.bks-trust-drows');
detail.id = 'bks-trust-detail-' + uid;
seals.forEach((s, i) => { s.id = 'bks-trust-seal-' + uid + '-' + i; s.setAttribute('aria-controls', detail.id); });
detail.setAttribute('aria-labelledby', seals[0].id);

function pickSeal(i, focus) {
  seals.forEach((s, j) => { s.setAttribute('aria-selected', String(j === i)); s.tabIndex = j === i ? 0 : -1; });
  detail.setAttribute('aria-labelledby', seals[i].id);
  if (focus) seals[i].focus();
  const S = D.seals[i];
  if (dName.textContent === S.name) return;
  dName.textContent = S.name;
  dRows.innerHTML = S.rows.map(([a, b]) => '<div><dt>' + esc(a) + '</dt><dd>' + esc(b) + '</dd></div>').join('');
  if (reduce.matches) return;
  [dName, ...dRows.children].forEach((el, k) => el.animate(
    [{ opacity: 0, transform: 'translateY(10px)', clipPath: 'inset(0 0 100% 0)' }, { opacity: 1, transform: 'none', clipPath: 'inset(0 0 0% 0)' }],
    { duration: 560, delay: k * 50, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }));
}
seals.forEach((s, i) => s.addEventListener('click', () => pickSeal(i)));
root.querySelector('.bks-trust-seals').addEventListener('keydown', (e) => {
  const i = seals.indexOf(document.activeElement);
  if (i < 0) return;
  const n = seals.length;
  const j = { ArrowRight: (i + 1) % n, ArrowDown: (i + 1) % n, ArrowLeft: (i - 1 + n) % n, ArrowUp: (i - 1 + n) % n, Home: 0, End: n - 1 }[e.key];
  if (j === undefined) return;
  e.preventDefault();
  pickSeal(j, true);
});

/* ---------- uptime ---------- */
const N = D.days;
const start = Date.UTC(D.start[0], D.start[1], D.start[2]);
const fmtDate = (d, year) => new Date(start + d * 864e5).toLocaleDateString('en-GB', year ? { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' } : { day: 'numeric', month: 'short', timeZone: 'UTC' });
const up = root.querySelector('.bks-trust-up');
const strip = root.querySelector('.bks-trust-days');
const days = [...strip.querySelectorAll('.bks-trust-day')];
const tip = root.querySelector('.bks-trust-tip');
const [tipB, tipS, tipE] = ['b', 'span', 'em'].map((t) => tip.querySelector(t));
const pctEl = root.querySelector('.bks-trust-pct');
const winEl = root.querySelector('.bks-trust-win');
const fromEl = root.querySelector('.bks-trust-from');
const downEl = root.querySelector('.bks-trust-down');
const incEl = root.querySelector('.bks-trust-inc');
const longEl = root.querySelector('.bks-trust-long');
const radios = [...root.querySelectorAll('.bks-trust-svc input')];
radios.forEach((r) => { r.name = 'bks-trust-svc-' + uid; });

let svc = 0, win = 0, cur = null, shownPct = null, raf = 0;

function perDay(s) {
  const m = new Array(N).fill(0), note = new Array(N).fill('');
  D.services[s].inc.forEach(([d, mins, t]) => { m[d] += mins; note[d] = note[d] ? note[d] + '; ' + t : t; });
  return { m, note };
}
const dayPct = (mins) => ((1440 - mins) / 1440 * 100).toFixed(2);
const stateOf = (mins) => (mins === 0 ? 'ok' : mins <= 30 ? 'minor' : 'major');

function tweenPct(to, animate) {
  if (!animate || reduce.matches || shownPct === null) { shownPct = to; pctEl.textContent = to.toFixed(3); return; }
  const from = shownPct, t0 = performance.now();
  cancelAnimationFrame(raf);
  const step = (now) => {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - t0) / 700), e = 1 - Math.pow(1 - p, 4);
    shownPct = from + (to - from) * e;
    pctEl.textContent = shownPct.toFixed(3);
    if (p < 1) raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
}

function render(animate) {
  cur = perDay(svc);
  const name = D.services[svc].name;
  days.forEach((b, d) => {
    const mins = cur.m[d];
    b.dataset.s = stateOf(mins);
    b.setAttribute('aria-label', fmtDate(d, true) + ': ' + dayPct(mins) + '% uptime' +
      (mins ? ', ' + (mins > 30 ? 'outage' : 'degraded') + ' for ' + mins + ' minutes. ' + cur.note[d] : ', no incidents'));
  });
  const from = N - win;
  let down = 0, inc = 0, longest = 0;
  D.services[svc].inc.forEach(([d, mins]) => { if (d >= from) { down += mins; inc++; longest = Math.max(longest, mins); } });
  winEl.textContent = win;
  fromEl.textContent = fmtDate(from);
  downEl.textContent = down + ' min';
  incEl.textContent = inc;
  longEl.textContent = inc ? longest + ' min' : '—';
  strip.setAttribute('aria-label', name + ' daily uptime, ' + fmtDate(from) + ' to ' + fmtDate(N - 1, true));
  tweenPct((1 - down / (win * 1440)) * 100, animate);
}

/* tooltip, shared by pointer and keyboard */
function showTip(b) {
  const d = days.indexOf(b), mins = cur.m[d];
  tipB.textContent = fmtDate(d, true);
  tipS.textContent = mins ? dayPct(mins) + '% · ' + (mins > 30 ? 'Outage' : 'Degraded') + ' for ' + mins + ' min' : '100% · No incidents';
  tipE.textContent = cur.note[d];
  const br = b.getBoundingClientRect(), ur = up.getBoundingClientRect();
  const tw = tip.offsetWidth;
  const x = Math.max(12, Math.min(ur.width - tw - 12, br.left - ur.left + br.width / 2 - tw / 2));
  const y = br.bottom - ur.top + 10; // below the strip, so the headline figure stays readable
  tip.style.transform = 'translate(' + Math.round(x) + 'px,' + Math.round(y) + 'px)';
  tip.classList.add('is-on');
}
const hideTip = () => tip.classList.remove('is-on');
const visibleDays = () => days.filter((b) => b.offsetParent !== null);

strip.addEventListener('pointerover', (e) => { const b = e.target.closest('.bks-trust-day'); if (b) showTip(b); });
strip.addEventListener('pointerleave', () => { if (!strip.contains(document.activeElement)) hideTip(); });
strip.addEventListener('focusin', (e) => {
  const b = e.target.closest('.bks-trust-day');
  if (!b) return;
  days.forEach((x) => { x.tabIndex = x === b ? 0 : -1; });
  showTip(b);
});
strip.addEventListener('focusout', (e) => { if (!strip.contains(e.relatedTarget)) hideTip(); });
strip.addEventListener('keydown', (e) => {
  const vis = visibleDays(), i = vis.indexOf(document.activeElement);
  if (i < 0) return;
  const step = e.shiftKey ? 7 : 1;
  const j = { ArrowRight: Math.min(vis.length - 1, i + step), ArrowLeft: Math.max(0, i - step), Home: 0, End: vis.length - 1 }[e.key];
  if (e.key === 'Escape') { hideTip(); return; }
  if (j === undefined) return;
  e.preventDefault();
  vis[j].focus();
});

radios.forEach((r) => r.addEventListener('change', () => {
  if (!r.checked) return;
  svc = +r.value;
  render(true);
  const f = strip.querySelector('.bks-trust-day:focus');
  if (f) showTip(f);
}));

// the visible window (45 or 90 days) is decided by a container query; JS follows it
function syncWindow() {
  const w = parseInt(getComputedStyle(strip).getPropertyValue('--bks-trust-window'), 10) || 90;
  if (w === win) return;
  win = w;
  const vis = visibleDays();
  if (!vis.some((b) => b.tabIndex === 0)) days.forEach((b, d) => { b.tabIndex = d === N - 1 ? 0 : -1; });
  hideTip();
  render(false);
}
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } syncWindow(); });
ro.observe(root);
syncWindow();

