.bks-laurels {
  /* re-theme with these four */
  --bks-laurels-bg: oklch(23.5% 0.034 166);
  --bks-laurels-ink: oklch(95% 0.018 88);
  --bks-laurels-gold: oklch(80% 0.105 82);
  --bks-laurels-serif: ui-serif, "New York", "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  --bks-laurels-muted: color-mix(in oklch, var(--bks-laurels-ink) 60%, var(--bks-laurels-bg));
  --bks-laurels-line: color-mix(in oklch, var(--bks-laurels-gold) 24%, var(--bks-laurels-bg));
  --bks-laurels-out: cubic-bezier(.16, 1, .3, 1);
  --bks-laurels-spring: linear(0, 0.058, 0.205, 0.398, 0.604, 0.797, 0.959, 1.08, 1.159, 1.198, 1.204, 1.186, 1.153, 1.112, 1.07, 1.032, 1.001, 0.978, 0.964, 0.958, 0.959, 0.963, 0.971, 0.98, 0.988, 0.995, 1.001, 1.005, 1.008, 1.009, 1.008, 1.007, 1.005, 1.004, 1);
  --bks-laurels-soft: linear(0, 0.042, 0.145, 0.283, 0.433, 0.579, 0.712, 0.826, 0.917, 0.985, 1.033, 1.063, 1.079, 1.084, 1.08, 1.071, 1.06, 1.047, 1.035, 1.024, 1.015, 1.007, 1.001, 0.997, 0.995, 0.993, 0.993, 0.993, 0.994, 0.995, 0.996, 0.997, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(60% 50% at 50% 0%, color-mix(in oklch, var(--bks-laurels-gold) 9%, transparent), transparent 70%),
    radial-gradient(120% 80% at 50% 120%, color-mix(in oklch, black 30%, transparent), transparent 60%),
    var(--bks-laurels-bg);
  color: var(--bks-laurels-ink);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, figure, blockquote, figcaption) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
}

.bks-laurels-in {
  padding: clamp(44px, 7.5cqi, 104px) clamp(16px, 5cqi, 64px) clamp(40px, 6.5cqi, 88px);
  display: grid; gap: clamp(28px, 4.5cqi, 56px);
  justify-items: center;
  text-align: center;
}

.bks-laurels-head { display: grid; gap: 14px; justify-items: center; }
.bks-laurels-kicker {
  display: flex; align-items: center; gap: 14px;
  font: 500 11px/1 system-ui, sans-serif; letter-spacing: .32em; text-transform: uppercase;
  color: var(--bks-laurels-gold);
  &::before, &::after { content: ""; width: 28px; height: 1px; background: currentColor; opacity: .55; }
}
.bks-laurels-title {
  font: 300 clamp(34px, 4.6cqi + 14px, 68px)/1.02 var(--bks-laurels-serif);
  letter-spacing: -.02em;
  text-wrap: balance;
  max-width: 16ch;
}
.bks-laurels-lede { font: italic 400 clamp(16px, .5cqi + 14px, 19px)/1.45 var(--bks-laurels-serif); color: var(--bks-laurels-muted); text-wrap: balance; }

/* ---------- the row of wreaths ---------- */
.bks-laurels-row {
  width: 100%;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(140px, 40%);
  gap: 8px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 6px 4px 10px;
  mask-image: linear-gradient(to right, transparent, #000 7%, #000 93%, transparent);
  &::-webkit-scrollbar { display: none; }
}
.bks-laurels-award {
  scroll-snap-align: center;
  display: grid; justify-items: center; align-content: start; gap: 4px;
  padding: 6px 6px 14px;
  border: 0; border-radius: 16px;
  background: transparent;
  cursor: pointer;
  &:focus-visible { outline: 1px solid var(--bks-laurels-gold); outline-offset: -2px; }
}
.bks-laurels-wreath {
  position: relative;
  width: min(100%, 196px); aspect-ratio: 1;
  display: block;
  & svg { width: 100%; height: 100%; display: block; overflow: visible; }
}
.bks-laurels-mid {
  position: absolute; inset: 0;
  display: grid; place-content: center; gap: 3px;
  & b { font: 400 clamp(26px, 2cqi + 16px, 34px)/1 var(--bks-laurels-serif); letter-spacing: -.01em; font-variant-numeric: lining-nums tabular-nums; color: var(--bks-laurels-ink); transition: color .5s var(--bks-laurels-out); }
  & small { font: 600 9px/1 system-ui, sans-serif; letter-spacing: .26em; text-transform: uppercase; color: var(--bks-laurels-gold); margin-right: -.26em; }
}
.bks-laurels-body {
  font: 400 15px/1.25 var(--bks-laurels-serif);
  text-wrap: balance;
  max-width: 16ch;
  margin-top: 6px;
  transition: color .4s var(--bks-laurels-out);
}
.bks-laurels-cat {
  font: 500 10px/1.3 system-ui, sans-serif; letter-spacing: .18em; text-transform: uppercase;
  color: var(--bks-laurels-muted);
  position: relative;
  padding-bottom: 10px;
  &::after {
    content: ""; position: absolute; left: 50%; bottom: 0;
    width: 22px; height: 1px; margin-left: -11px;
    background: var(--bks-laurels-gold);
    scale: 0 1;
    transition: scale .6s var(--bks-laurels-out);
  }
}

/* SVG parts — leaves are generated by the script */
.bks-laurels-stem {
  fill: none; stroke: color-mix(in oklch, var(--bks-laurels-gold) 70%, var(--bks-laurels-bg)); stroke-width: 1.6; stroke-linecap: round;
  stroke-dasharray: 1; stroke-dashoffset: 0;
  transition: stroke-dashoffset 1.1s var(--bks-laurels-out) calc(var(--i) * 120ms);
}
.bks-laurels-leaf {
  transform-box: view-box;
  transform-origin: 0 0;
  fill: color-mix(in oklch, var(--bks-laurels-gold) calc(52% + var(--t) * 48%), var(--bks-laurels-bg));
  transition:
    scale .95s var(--bks-laurels-spring) calc(var(--i) * 120ms + var(--k) * 48ms + 150ms),
    fill .5s var(--bks-laurels-out);
  &.is-inner { fill: color-mix(in oklch, var(--bks-laurels-gold) calc(36% + var(--t) * 40%), var(--bks-laurels-bg)); }
}
.bks-laurels-berry { fill: var(--bks-laurels-gold); transform-box: fill-box; transform-origin: center; transition: scale .6s var(--bks-laurels-spring) calc(var(--i) * 120ms + 700ms); }

/* armed by JS, revealed once the row is on screen */
.bks-laurels.is-armed:not(.is-in) {
  & .bks-laurels-leaf, & .bks-laurels-berry { scale: 0; }
  & .bks-laurels-stem { stroke-dashoffset: 1; }
}

/* hover: the leaves rustle tip-ward */
@keyframes bks-laurels-rustle {
  0%, 100% { rotate: 0deg; }
  30% { rotate: -9deg; }
  65% { rotate: 3.5deg; }
}
.bks-laurels-award:hover .bks-laurels-leaf { animation: bks-laurels-rustle .9s var(--bks-laurels-out) calc(var(--k) * 32ms) both; }

/* selection: the chosen wreath is lit, the rest step back */
.bks-laurels-award[aria-selected="false"] {
  & .bks-laurels-wreath svg { opacity: .55; transition: opacity .5s var(--bks-laurels-out); }
  & .bks-laurels-mid b { color: var(--bks-laurels-muted); }
  & .bks-laurels-body { color: var(--bks-laurels-muted); }
  &:hover .bks-laurels-wreath svg { opacity: .9; }
}
.bks-laurels-award[aria-selected="true"] {
  & .bks-laurels-wreath svg { opacity: 1; transition: opacity .5s var(--bks-laurels-out); filter: drop-shadow(0 0 18px color-mix(in oklch, var(--bks-laurels-gold) 22%, transparent)); }
  & .bks-laurels-cat::after { scale: 1 1; }
}

/* ---------- citation ---------- */
.bks-laurels-cite {
  display: grid; gap: 18px; justify-items: center;
  width: min(100%, 760px);
  min-height: 11.5em;
  align-content: start;
}
.bks-laurels-q {
  font: italic 400 clamp(21px, 1.9cqi + 13px, 32px)/1.3 var(--bks-laurels-serif);
  letter-spacing: -.005em;
  text-wrap: balance;
  max-width: 30ch;
  quotes: "\201C" "\201D";
  & p::before { content: open-quote; color: var(--bks-laurels-gold); margin-right: .04em; }
  & p::after { content: close-quote; color: var(--bks-laurels-gold); margin-left: .02em; }
}
.bks-laurels-w {
  display: inline-block;
  transition: opacity .7s var(--bks-laurels-out), filter .7s var(--bks-laurels-out), translate .9s var(--bks-laurels-soft);
  transition-delay: calc(var(--j) * 18ms);
  @starting-style { opacity: 0; filter: blur(6px); translate: 0 .4em; }
}
.bks-laurels-by {
  font: 500 10.5px/1.4 system-ui, sans-serif; letter-spacing: .22em; text-transform: uppercase;
  color: var(--bks-laurels-gold);
}

@container (min-width: 780px) {
  .bks-laurels-row {
    grid-auto-flow: row;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    overflow: visible;
    mask-image: none;
    gap: clamp(8px, 1.5cqi, 24px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bks-laurels {
    & .bks-laurels-leaf, & .bks-laurels-berry, & .bks-laurels-stem, & .bks-laurels-w { transition: fill .3s linear, opacity .3s linear; }
    & .bks-laurels-award:hover .bks-laurels-leaf { animation: none; }
  }
  .bks-laurels.is-armed:not(.is-in) {
    & .bks-laurels-leaf, & .bks-laurels-berry { scale: 1; }
    & .bks-laurels-stem { stroke-dashoffset: 0; }
  }
  .bks-laurels-w { @starting-style { filter: none; translate: none; } }
}

