// Citations, in the same order as the wreaths.
const CITES = [
  ['Oriel treats a ninety-thousand-word manuscript with the same calm it gives a postcard. Nothing else on our shortlist came close.', 'Jury citation · The Fennimore Prize, 2026'],
  ['Every animation earns its place, and most of them you only notice when you go looking for them. That restraint is the craft.', 'Jury citation · Northlight Design Awards, 2025'],
  ['Fully usable by voice, by switch and by screen reader from its very first release, not as an apology three versions later.', 'Laureate citation · The Cartwright Medal, 2025'],
  ['The first editor in years that made our staff writers stop complaining about their editor.', 'Editor’s pick · The Harrow Review, 2024'],
  ['Hanging punctuation, true small capitals, optical margins. Oriel sets text the way a good compositor would.', 'Silver citation · Ostwald Typographic Society, 2024']
];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const awards = [...root.querySelectorAll('.bks-laurels-award')];
const row = root.querySelector('.bks-laurels-row');
const cite = root.querySelector('.bks-laurels-cite');
const q = root.querySelector('.bks-laurels-q p');
const by = root.querySelector('.bks-laurels-by');
const uid = Math.random().toString(36).slice(2, 8);
const R = 71, CX = 100, CY = 100, rad = (d) => d * Math.PI / 180;
const f = (n) => +n.toFixed(2);

/* ---------- procedural laurel: one branch is built, the other is its mirror ---------- */
function leafPath(L, h) {
  // a slightly asymmetric leaf, base at the origin, tip along +x
  return 'M0 0C' + f(L * .28) + ' ' + f(-h * 1.7) + ' ' + f(L * .74) + ' ' + f(-h * 1.25) + ' ' + f(L) + ' 0' +
    'C' + f(L * .7) + ' ' + f(h * 1.05) + ' ' + f(L * .3) + ' ' + f(h * 1.35) + ' 0 0Z';
}
function branch(n, a0, a1, Lmax) {
  const p = (a) => [CX + R * Math.cos(rad(a)), CY + R * Math.sin(rad(a))];
  const [x0, y0] = p(a0), [x1, y1] = p(a1);
  let s = '<path class="bks-laurels-stem" pathLength="1" d="M' + f(x0) + ' ' + f(y0) + 'A' + R + ' ' + R + ' 0 0 1 ' + f(x1) + ' ' + f(y1) + '"/>';
  for (let k = 0; k < n; k++) {
    const t = (k + 0.6) / (n + 0.4), a = a0 + (a1 - a0) * t;
    const [x, y] = p(a);
    const tan = [-Math.sin(rad(a)), Math.cos(rad(a))], out = [Math.cos(rad(a)), Math.sin(rad(a))];
    const L = Lmax * (1 - 0.38 * t);
    [[38, 1, ''], [-30, 0.82, ' is-inner']].forEach(([deg, scale, cls]) => {
      const c = Math.cos(rad(Math.abs(deg))), sn = Math.sin(rad(Math.abs(deg))) * Math.sign(deg);
      const dx = tan[0] * c + out[0] * sn, dy = tan[1] * c + out[1] * sn;
      const ang = Math.atan2(dy, dx) * 180 / Math.PI;
      const len = L * scale;
      s += '<g transform="translate(' + f(x) + ' ' + f(y) + ') rotate(' + f(ang) + ')"><path class="bks-laurels-leaf' + cls + '" style="--k:' + k + ';--t:' + f(t) + '" d="' + leafPath(len, len * 0.2) + '"/></g>';
    });
    // a berry tucked inside every third node
    if (k % 3 === 1) {
      const bx = x - out[0] * 7 + tan[0] * 2, by2 = y - out[1] * 7 + tan[1] * 2;
      s += '<circle class="bks-laurels-berry" cx="' + f(bx) + '" cy="' + f(by2) + '" r="1.9"/>';
    }
  }
  // terminal leaf continues the stem's direction
  const tan = [-Math.sin(rad(a1)), Math.cos(rad(a1))];
  s += '<g transform="translate(' + f(x1) + ' ' + f(y1) + ') rotate(' + f(Math.atan2(tan[1], tan[0]) * 180 / Math.PI) + ')"><path class="bks-laurels-leaf" style="--k:' + n + ';--t:1" d="' + leafPath(Lmax * 0.6, Lmax * 0.6 * 0.2) + '"/></g>';
  return s;
}
awards.forEach((b) => {
  const n = +b.dataset.n, a0 = +b.dataset.a0, a1 = +b.dataset.a1, L = +b.dataset.l;
  const half = branch(n, a0, a1, L);
  // a0 sits just past the bottom, so the mirrored stems cross like a tied wreath
  b.querySelector('svg').innerHTML = '<g>' + half + '</g><g transform="translate(200 0) scale(-1 1)">' + half + '</g>';
});

/* ---------- tabs + citation ---------- */
cite.id = 'bks-laurels-cite-' + uid;
awards.forEach((b, i) => { b.id = 'bks-laurels-award-' + uid + '-' + i; b.setAttribute('aria-controls', cite.id); });
cite.setAttribute('aria-labelledby', awards[0].id);

function words(text) {
  // each word becomes an inline-block that enters through @starting-style
  return text.split(' ').map((w, j) => '<span class="bks-laurels-w" style="--j:' + j + '">' + w.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</span>').join(' ');
}
let cur = 0, swapT = 0;
function select(i, focus) {
  awards.forEach((b, j) => { b.setAttribute('aria-selected', String(j === i)); b.tabIndex = j === i ? 0 : -1; });
  cite.setAttribute('aria-labelledby', awards[i].id);
  if (focus) awards[i].focus();
  if (row.scrollWidth > row.clientWidth) {
    const b = awards[i];
    row.scrollTo({ left: b.offsetLeft - (row.clientWidth - b.offsetWidth) / 2, behavior: reduce.matches ? 'auto' : 'smooth' });
  }
  if (i === cur) return;
  cur = i;
  clearTimeout(swapT);
  const put = () => { q.innerHTML = words(CITES[i][0]); by.textContent = CITES[i][1]; };
  if (reduce.matches) { put(); return; }
  q.animate([{ opacity: 1 }, { opacity: 0, filter: 'blur(4px)' }], { duration: 160, easing: 'ease-in', fill: 'forwards' });
  swapT = setTimeout(() => {
    if (!root.isConnected) return;
    q.getAnimations().forEach((a) => a.cancel());
    put();
  }, 160);
}
awards.forEach((b, i) => b.addEventListener('click', () => select(i)));
row.addEventListener('keydown', (e) => {
  const i = awards.indexOf(document.activeElement);
  if (i < 0) return;
  const n = awards.length;
  const j = { ArrowRight: (i + 1) % n, ArrowLeft: (i - 1 + n) % n, Home: 0, End: n - 1 }[e.key];
  if (j === undefined) return;
  e.preventDefault();
  select(j, true);
});

/* ---------- grow the wreaths once they are on screen ---------- */
if (!reduce.matches && 'IntersectionObserver' in window) {
  root.classList.add('is-armed');
  const io = new IntersectionObserver((es) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (!es.some((e) => e.isIntersecting)) return;
    io.disconnect();
    // one frame in the armed state first, so the transition has a start value
    requestAnimationFrame(() => { if (!root.isConnected) return; root.classList.add('is-in'); });
  }, { threshold: 0.35 });
  io.observe(row);
}

