.bks-live {
  /* re-theme with these four */
  --bks-live-bg: oklch(89% 0.18 98);
  --bks-live-ink: oklch(16% 0.01 90);
  --bks-live-paper: oklch(98.5% 0.01 95);
  --bks-live-bw: 3px;

  --bks-live-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bks-live-shadow: 7px 7px 0 var(--bks-live-ink);
  --bks-live-faint: color-mix(in oklch, var(--bks-live-ink) 24%, var(--bks-live-paper));
  --bks-live-snap: cubic-bezier(.2, 1.4, .4, 1);

  container-type: inline-size;
  container-name: bks-live;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-live-bg);
  color: var(--bks-live-ink);
  font: 500 15px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; }
}
.bks-live-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bks-live-in {
  padding: clamp(28px, 5cqi, 64px) clamp(16px, 4cqi, 56px) clamp(28px, 4.5cqi, 56px);
  display: grid; gap: clamp(20px, 3cqi, 32px);
}

/* ---------- header ---------- */
.bks-live-head {
  display: grid; gap: 14px 24px;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "tag tag" "title title" "clock clock" "ctrl ctrl";
  align-items: end;
}
.bks-live-tag {
  grid-area: tag;
  font: 700 11.5px/1.2 var(--bks-live-mono); letter-spacing: .04em;
  border-block: var(--bks-live-bw) solid var(--bks-live-ink);
  padding: 7px 0;
}
.bks-live-title {
  grid-area: title;
  font: 900 clamp(46px, 9.4cqi, 132px)/.84 system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  letter-spacing: -.06em;
  text-transform: uppercase;
  text-wrap: balance;
  margin-left: -.04em;
}
.bks-live-clock {
  grid-area: clock;
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  border: var(--bks-live-bw) solid var(--bks-live-ink);
  background: var(--bks-live-ink); color: var(--bks-live-bg);
  padding: 8px 12px 9px;
}
.bks-live-clabel { font: 700 11px/1 var(--bks-live-mono); letter-spacing: .08em; text-transform: uppercase; }
.bks-live-time { font: 700 clamp(26px, 2.6cqi + 12px, 38px)/1 var(--bks-live-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }

.bks-live-ctrl { grid-area: ctrl; display: flex; flex-wrap: wrap; gap: 10px; align-items: stretch; }
.bks-live-speed {
  display: flex; flex: 1 1 auto;
  border: var(--bks-live-bw) solid var(--bks-live-ink);
  background: var(--bks-live-paper);
  box-shadow: 4px 4px 0 var(--bks-live-ink);
  & legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  & label { position: relative; flex: 1 1 0; display: grid; place-items: center; min-height: 40px; cursor: pointer; }
  & label + label { border-left: var(--bks-live-bw) solid var(--bks-live-ink); }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & span { font: 700 12px/1 var(--bks-live-mono); text-transform: uppercase; letter-spacing: .02em; padding: 0 10px; white-space: nowrap; }
  & label:has(input:checked) { background: var(--bks-live-ink); color: var(--bks-live-bg); }
  & label:hover:not(:has(input:checked)) { background: var(--bks-live-bg); }
  & label:has(input:focus-visible) { outline: var(--bks-live-bw) solid var(--bks-live-ink); outline-offset: 3px; z-index: 1; }
}
.bks-live-pause {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 0 14px; min-height: 46px;
  border: var(--bks-live-bw) solid var(--bks-live-ink);
  background: var(--bks-live-paper);
  box-shadow: 4px 4px 0 var(--bks-live-ink);
  font: 700 12px/1 var(--bks-live-mono); text-transform: uppercase;
  cursor: pointer;
  transition: translate .08s linear, box-shadow .08s linear;
  & svg { width: 14px; height: 14px; fill: currentColor; }
  & .bks-live-iy { display: none; }
  &[aria-pressed="true"] { background: var(--bks-live-ink); color: var(--bks-live-bg); }
  &[aria-pressed="true"] .bks-live-ip { display: none; }
  &[aria-pressed="true"] .bks-live-iy { display: inline; }
  &:active { translate: 4px 4px; box-shadow: 0 0 0 var(--bks-live-ink); }
  &:focus-visible { outline: var(--bks-live-bw) solid var(--bks-live-ink); outline-offset: 3px; }
}

/* ---------- cards ---------- */
.bks-live-grid {
  display: grid; gap: 18px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "lab" "ev" "rt" "co";
  padding: 0 7px 7px 0; /* room for the hard shadows */
}
.bks-live-card {
  container-type: inline-size;
  display: grid; align-content: start; gap: 6px;
  min-width: 0;
  padding: 14px 16px 16px;
  border: var(--bks-live-bw) solid var(--bks-live-ink);
  background: var(--bks-live-paper);
  box-shadow: var(--bks-live-shadow);
}
.bks-live-lab { grid-area: lab; }
.bks-live-ev { grid-area: ev; }
.bks-live-rt { grid-area: rt; }
.bks-live-co { grid-area: co; background: var(--bks-live-ink); color: var(--bks-live-bg); }
.bks-live-label { font: 700 12px/1.25 var(--bks-live-mono); text-transform: uppercase; letter-spacing: .03em; }
.bks-live-num {
  font: 850 clamp(36px, 15cqi, 92px)/.92 system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  letter-spacing: -.055em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden; text-overflow: clip;
  margin-block: 6px 2px;
}
.bks-live-rate {
  font: 600 11.5px/1.3 var(--bks-live-mono);
  padding-top: 8px; margin-top: 2px;
  border-top: 2px dashed currentColor;
  opacity: .82;
}
.bks-live-cad {
  justify-self: start;
  margin-top: 8px;
  padding: 3px 7px 4px;
  font: 700 11px/1.2 var(--bks-live-mono); text-transform: uppercase; letter-spacing: .02em;
  background: var(--bks-live-bg); color: var(--bks-live-ink);
  box-shadow: inset 0 0 0 2px var(--bks-live-ink);
}

/* the 10 × 10 sheet: one square per label (or per 100 / 10,000 when warped) */
.bks-live-sheet {
  display: grid; grid-template-columns: repeat(10, 1fr); gap: 3px;
  margin-top: 12px;
  max-width: 300px;
  & i {
    position: relative; aspect-ratio: 1;
    box-shadow: inset 0 0 0 1.5px var(--bks-live-faint);
    &::after {
      content: ""; position: absolute; inset: 0;
      background: var(--bks-live-ink);
      scale: 0;
      transition: scale .22s var(--bks-live-snap);
    }
    &.is-on::after { scale: 1; }
  }
  &.is-full { animation: bks-live-stamp .42s steps(2, jump-none) 2; }
}
@keyframes bks-live-stamp {
  from { background: var(--bks-live-ink); }
  to { background: transparent; }
}
.bks-live-sheetcap {
  display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap;
  max-width: 300px;
  font: 700 11px/1.3 var(--bks-live-mono); text-transform: uppercase;
  font-variant-numeric: tabular-nums;
}

.bks-live-foot { font: 600 11.5px/1.45 var(--bks-live-mono); max-width: 70ch; text-wrap: pretty; }

/* paused: everything greys out a step so the state is legible from a distance */
.bks-live:has(.bks-live-pause[aria-pressed="true"]) .bks-live-num { opacity: .45; }

@container bks-live (min-width: 600px) {
  .bks-live-head { grid-template-areas: "tag tag" "title title" "ctrl clock"; }
  .bks-live-clock { flex-direction: column; align-items: flex-end; gap: 6px; min-width: 200px; }
  .bks-live-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-areas: "lab lab" "ev rt" "co co";
  }
}
@container bks-live (min-width: 960px) {
  .bks-live-grid {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr) minmax(0, 1fr);
    grid-template-areas: "lab ev rt" "lab co co";
    gap: 22px;
  }
  .bks-live-lab { grid-template-rows: auto auto auto auto 1fr auto; }
  .bks-live-sheet { align-self: end; }
  .bks-live-ev, .bks-live-rt, .bks-live-co { grid-template-rows: auto auto auto 1fr; }
  .bks-live-ev .bks-live-cad, .bks-live-rt .bks-live-cad, .bks-live-co .bks-live-cad { align-self: end; }
}

@media (prefers-reduced-motion: reduce) {
  .bks-live {
    & .bks-live-sheet i::after { transition: none; }
    & .bks-live-sheet.is-full { animation: none; }
    & .bks-live-pause { transition: none; }
  }
}

