// 2025 totals. Each counter is rate × simulated seconds, so the numbers can never disagree with their footnotes.
const YEAR_S = 31536000;
const STATS = [
  { perYear: 412e6, unit: '', dec: 0, rateNote: (r) => '412,000,000 / yr → ' + r.toFixed(2) + ' / sec' },
  { perYear: 9.8e9, unit: '', dec: 0, rateNote: (r) => '9,800,000,000 / yr → ' + r.toFixed(2) + ' / sec' },
  { perYear: 27.4e9, unit: '', dec: 0, rateNote: (r) => '27,400,000,000 / yr → ' + r.toFixed(2) + ' / sec' },
  { perYear: 61.3e6, unit: ' kg', dec: 1, rateNote: (r) => '61,300 t / yr → ' + r.toFixed(2) + ' kg / sec' }
];
STATS.forEach((s) => { s.rate = s.perYear / YEAR_S; });
// one square on the sheet stands for this many labels at each speed
const SHEET_UNIT = { 1: 1, 60: 100, 3600: 10000 };

const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const cards = [...root.querySelectorAll('.bks-live-card')];
const nums = cards.map((c) => c.querySelector('.bks-live-num'));
const time = root.querySelector('.bks-live-time');
const clabel = root.querySelector('.bks-live-clabel');
const sheet = root.querySelector('.bks-live-sheet');
const unitEl = root.querySelector('.bks-live-unit');
const sheetsEl = root.querySelector('.bks-live-sheets');
const pauseBtn = root.querySelector('.bks-live-pause');
const radios = [...root.querySelectorAll('.bks-live-speed input')];
const sr = root.querySelector('.bks-live-sr');

const uid = Math.random().toString(36).slice(2, 8);
radios.forEach((r) => { r.name = 'bks-live-speed-' + uid; });
const cadence = (s) => {
  const ms = 1000 / s.rate;
  return s.unit ? 'Real time: 1 kg every ' + (ms / 1000).toFixed(2) + ' s' : 'Real time: one every ' + (ms >= 10 ? Math.round(ms) : ms.toFixed(1)) + ' ms';
};
cards.forEach((c, k) => {
  c.querySelector('.bks-live-rate').textContent = STATS[k].rateNote(STATS[k].rate);
  c.querySelector('.bks-live-cad').textContent = cadence(STATS[k]);
});

sheet.innerHTML = '<i></i>'.repeat(100);
const cells = [...sheet.children];

const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const nf1 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const pad = (n) => String(n).padStart(2, '0');

let sim = 0;            // simulated seconds on the page
let warp = 1, target = 1;
let paused = false, visible = false, raf = 0, tick = 0, last = 0;
let lastFilled = 0, lastSheets = -1, lastUnit = 0;

function clock(s) {
  const t = Math.floor(s), d = Math.floor(t / 86400), h = Math.floor(t / 3600) % 24, m = Math.floor(t / 60) % 60, sec = t % 60;
  return (d ? d + 'd ' : '') + pad(h) + ':' + pad(m) + ':' + pad(sec);
}

function render() {
  STATS.forEach((s, k) => {
    const v = s.rate * sim;
    const txt = (s.dec ? nf1.format(Math.floor(v * 10) / 10) : nf0.format(Math.floor(v))) + s.unit;
    if (nums[k].textContent !== txt) nums[k].textContent = txt;
  });
  const c = clock(sim);
  if (time.textContent !== c) time.textContent = c;

  const unit = SHEET_UNIT[target];
  const count = Math.floor(STATS[0].rate * sim / unit);
  const filled = count % 100, sheets = Math.floor(count / 100);
  if (unit !== lastUnit) {
    lastUnit = unit;
    unitEl.textContent = '1 ■ = ' + nf0.format(unit) + (unit === 1 ? ' label' : ' labels');
    cells.forEach((el, i) => el.classList.toggle('is-on', i < filled));
    lastFilled = filled;
  } else if (filled !== lastFilled) {
    if (filled < lastFilled) {
      // a sheet just filled: stamp it, then start a fresh one
      cells.forEach((el) => el.classList.remove('is-on'));
      if (!reduce.matches) { sheet.classList.remove('is-full'); void sheet.offsetWidth; sheet.classList.add('is-full'); }
      for (let i = 0; i < filled; i++) cells[i].classList.add('is-on');
    } else {
      for (let i = lastFilled; i < filled; i++) cells[i].classList.add('is-on');
    }
    lastFilled = filled;
  }
  if (sheets !== lastSheets) { lastSheets = sheets; sheetsEl.textContent = nf0.format(sheets) + (sheets === 1 ? ' sheet' : ' sheets') + ' filled'; }
}

const running = () => visible && !paused && !document.hidden;

function advance(now) {
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;
  // speed changes ramp in log space, so 1× → 3600× feels like acceleration, not a jump
  if (warp !== target) {
    const lw = Math.log(warp), lt = Math.log(target);
    const nlw = reduce.matches ? lt : lw + (lt - lw) * (1 - Math.exp(-dt / 0.45));
    warp = Math.abs(nlw - lt) < 0.01 ? target : Math.exp(nlw);
  }
  sim += dt * warp;
  render();
}

function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!running()) return;
  advance(now);
  raf = requestAnimationFrame(frame);
}

function start() {
  if (!running()) return;
  last = performance.now();
  if (reduce.matches) {
    // calm version: one honest update per second, no frame loop
    if (!tick) tick = setInterval(() => {
      if (!root.isConnected) { cleanup(); return; }
      if (!running()) return;
      advance(performance.now());
    }, 1000);
  } else if (!raf) {
    raf = requestAnimationFrame(frame);
  }
}

radios.forEach((r) => r.addEventListener('change', () => {
  if (!r.checked) return;
  target = +r.value;
  clabel.textContent = target === 1 ? 'On this page' : 'Simulated';
  sr.textContent = target === 1 ? 'Counting in real time' : 'Counting at ' + (target === 60 ? 'one minute' : 'one hour') + ' per second';
  render();
}));

pauseBtn.addEventListener('click', () => {
  paused = !paused;
  pauseBtn.setAttribute('aria-pressed', String(paused));
  pauseBtn.querySelector('span').textContent = paused ? 'Resume' : 'Pause';
  sr.textContent = paused ? 'Counters paused' : 'Counters running';
  if (!paused) start();
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { cleanup(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { threshold: 0.15 });
io.observe(root);

function onVis() {
  if (!root.isConnected) { cleanup(); return; }
  if (!document.hidden) start();
}
document.addEventListener('visibilitychange', onVis);

function cleanup() {
  io.disconnect();
  clearInterval(tick);
  document.removeEventListener('visibilitychange', onVis);
}

render();

