@property --bks-sync-x { syntax: "<number>"; inherits: true; initial-value: 1; }
@property --bks-sync-y { syntax: "<number>"; inherits: true; initial-value: .5; }

.bks-sync {
  /* re-theme with these four */
  --bks-sync-bg: oklch(20% 0.013 105);
  --bks-sync-ink: oklch(94% 0.012 100);
  --bks-sync-accent: oklch(73% 0.17 52);
  --bks-sync-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --bks-sync-muted: color-mix(in oklch, var(--bks-sync-ink) 55%, var(--bks-sync-bg));
  --bks-sync-line: color-mix(in oklch, var(--bks-sync-ink) 11%, var(--bks-sync-bg));
  --bks-sync-card: color-mix(in oklch, var(--bks-sync-ink) 3.5%, var(--bks-sync-bg));
  --bks-sync-out: cubic-bezier(.16, 1, .3, 1);
  --bks-sync-glide: .42s;

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-sync-bg);
  color: var(--bks-sync-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --bks-sync-x var(--bks-sync-glide) var(--bks-sync-out);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p) { margin: 0; padding: 0; }
  &.is-scrub { --bks-sync-glide: .09s; }
}

.bks-sync-in {
  padding: clamp(36px, 6.5cqi, 84px) clamp(16px, 5cqi, 64px);
  display: grid; gap: clamp(24px, 3.5cqi, 40px);
}

/* ---------- header ---------- */
.bks-sync-head {
  display: grid; gap: 14px 48px;
  grid-template-areas: "kicker" "title" "lede" "read";
}
.bks-sync-kicker {
  grid-area: kicker;
  display: flex; align-items: center; gap: 8px;
  font: 500 11.5px/1 var(--bks-sync-mono); letter-spacing: .1em; text-transform: uppercase;
  color: var(--bks-sync-accent);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
}
.bks-sync-title {
  grid-area: title;
  font-size: clamp(28px, 3.3cqi + 14px, 50px); font-weight: 650;
  line-height: 1.04; letter-spacing: -.035em;
  text-wrap: balance;
  max-width: 19ch;
}
.bks-sync-lede { grid-area: lede; color: var(--bks-sync-muted); max-width: 52ch; text-wrap: pretty; }
.bks-sync-read {
  grid-area: read;
  display: grid; gap: 8px; align-content: end;
}
.bks-sync-wk {
  display: flex; align-items: baseline; gap: 10px;
  font-family: var(--bks-sync-mono);
  & span { font-size: 11.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--bks-sync-muted); }
  & b { font-size: clamp(40px, 3cqi + 24px, 60px); font-weight: 600; line-height: .9; letter-spacing: -.04em; font-variant-numeric: tabular-nums; min-width: 2ch; text-align: right; }
  & small { font-size: 12px; color: var(--bks-sync-muted); }
}
.bks-sync-evs { display: flex; flex-wrap: wrap; gap: 6px; }
.bks-sync-evk {
  font: 500 11px/1 var(--bks-sync-mono);
  padding: 6px 8px; border-radius: 6px;
  border: 1px dashed var(--bks-sync-line);
  color: var(--bks-sync-muted);
  transition: color .3s var(--bks-sync-out), border-color .3s, background-color .3s;
  &.is-past { color: var(--bks-sync-ink); border-color: color-mix(in oklch, var(--bks-sync-accent) 55%, var(--bks-sync-bg)); background: color-mix(in oklch, var(--bks-sync-accent) 10%, transparent); }
}

/* ---------- cards ---------- */
.bks-sync-cards {
  display: grid; gap: 10px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.bks-sync-card {
  display: grid; gap: 6px;
  grid-template-rows: auto auto auto 1fr;
  padding: 13px 12px 12px;
  border-radius: 14px;
  background: var(--bks-sync-card);
  box-shadow: inset 0 0 0 1px var(--bks-sync-line);
  transition: box-shadow .3s var(--bks-sync-out);
  &:has(.bks-sync-plot:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--bks-sync-accent); }
}
.bks-sync-ch {
  display: grid; grid-template-columns: 16px minmax(0, 1fr); gap: 2px 8px; align-items: center;
  & svg { width: 16px; height: 16px; fill: none; stroke: var(--bks-sync-muted); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & h3 { font-size: 13.5px; font-weight: 600; letter-spacing: -.005em; }
  & p { grid-column: 2; font: 500 10.5px/1.2 var(--bks-sync-mono); color: var(--bks-sync-muted); letter-spacing: .02em; }
}
.bks-sync-val {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 8px; margin-top: 8px;
  & .bks-sync-num { font-size: clamp(28px, 1.8cqi + 20px, 42px); font-weight: 650; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & .bks-sync-unit { font-size: 12.5px; color: var(--bks-sync-muted); }
}
.bks-sync-delta {
  font: 500 12px/1.3 var(--bks-sync-mono); color: var(--bks-sync-muted);
  font-variant-numeric: tabular-nums;
  & b { font-weight: 600; color: var(--bks-sync-ink); }
  & span { white-space: nowrap; }
  &[data-good="true"] b { color: var(--bks-sync-accent); }
  &[data-base="true"] b { color: var(--bks-sync-muted); }
}

.bks-sync-plot {
  --bks-sync-pad: 6px;
  position: relative;
  align-self: end;
  height: clamp(60px, 4cqi + 44px, 76px); margin-top: 10px;
  border-radius: 8px;
  cursor: crosshair;
  touch-action: pan-y;
  outline: none;
  background:
    linear-gradient(to right, var(--bks-sync-line) 1px, transparent 1px) 0 0 / calc(100% / 5) 100%,
    linear-gradient(var(--bks-sync-line), var(--bks-sync-line)) 0 100% / 100% 1px no-repeat;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
}
.bks-sync-area { fill: color-mix(in oklch, var(--bks-sync-accent) 14%, transparent); }
.bks-sync-pre { fill: none; stroke: var(--bks-sync-muted); stroke-width: 1.6; stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; }
.bks-sync-line { fill: none; stroke: var(--bks-sync-accent); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.bks-sync-ev { fill: none; stroke: color-mix(in oklch, var(--bks-sync-ink) 30%, var(--bks-sync-bg)); stroke-width: 1; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }

/* one shared --bks-sync-x (on the root) drives every crosshair; each card owns its --bks-sync-y */
.bks-sync-card { transition: --bks-sync-y var(--bks-sync-glide) var(--bks-sync-out); }
.bks-sync-xh {
  position: absolute; top: -4px; bottom: 0; left: 0; width: 1px;
  background: var(--bks-sync-ink);
  opacity: .5;
  translate: calc(var(--bks-sync-x) * (var(--bks-sync-w, 0) * 1px)) 0;
}
.bks-sync-dot {
  position: absolute; left: -5px; top: -5px; width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--bks-sync-bg);
  box-shadow: inset 0 0 0 2.5px var(--bks-sync-accent), 0 0 0 4px color-mix(in oklch, var(--bks-sync-accent) 22%, transparent);
  translate:
    calc(var(--bks-sync-x) * (var(--bks-sync-w, 0) * 1px))
    calc(var(--bks-sync-y) * (var(--bks-sync-h, 0) * 1px));
}

@container (min-width: 600px) {
  .bks-sync-cards { gap: 12px; }
  .bks-sync-card { padding: 16px 16px 14px; }
}
@container (min-width: 980px) {
  .bks-sync-head {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "kicker kicker" "title read" "lede read";
  }
  .bks-sync-read { justify-items: end; }
  .bks-sync-cards { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .bks-sync, .bks-sync-card { transition: none; }
  .bks-sync { & .bks-sync-evk { transition: none; } }
}

