// 26 weekly medians per metric. Every number on the cards is read from these arrays.
const D = {"n": 26, "events": [3, 10], "metrics": [{"fmt": "d1", "better": "up", "v": [3.1, 3.2, 3.2, 3.1, 5.0, 7.5, 8.9, 9.5, 10.9, 11.7, 12.7, 14.8, 14.7, 14.9, 16.4, 16.1, 17.3, 17.8, 17.2, 17.1, 17.9, 17.7, 18.6, 18.5, 18.1, 18.4]}, {"fmt": "h1", "better": "down", "v": [26.5, 25.4, 26.7, 25.5, 23.2, 19.6, 17.3, 16.4, 14.8, 12.3, 11.6, 9.9, 8.9, 7.8, 6.8, 5.9, 5.2, 4.8, 4.5, 4.2, 4.1, 3.8, 3.5, 3.4, 3.2, 3.2]}, {"fmt": "p1", "better": "down", "v": [17.0, 16.5, 17.4, 16.0, 16.0, 13.2, 12.8, 11.9, 11.9, 11.0, 10.1, 9.3, 8.7, 7.9, 7.5, 7.9, 7.6, 7.0, 6.9, 6.5, 6.4, 6.7, 6.1, 6.4, 6.0, 6.2]}, {"fmt": "hm", "better": "down", "v": [250, 262, 237, 253, 208, 211, 161, 145, 149, 123, 107, 95, 90, 78, 69, 65, 62, 51, 50, 47, 44, 44, 42, 42, 38, 38]}]};
const N = D.n;
const VW = 260, VH = 64, PAD = 7;
const cards = [...root.querySelectorAll('.bks-sync-card')];
const plots = cards.map((c) => c.querySelector('.bks-sync-plot'));
const wkEl = root.querySelector('.bks-sync-wk b');
const evks = [...root.querySelectorAll('.bks-sync-evk')];

const FMT = {
  d1: (v) => v.toFixed(1),
  h1: (v) => v.toFixed(1),
  p1: (v) => v.toFixed(1) + '%',
  hm: (v) => (v >= 60 ? Math.floor(v / 60) + 'h ' + String(v % 60).padStart(2, '0') + 'm' : v + 'm')
};
const SPOKEN = { d1: ' deploys per day', h1: ' hours', p1: '', hm: '' };

/* ---------- draw each sparkline once, in viewBox units ---------- */
const geo = D.metrics.map((m, k) => {
  const lo = Math.min(...m.v), hi = Math.max(...m.v);
  const X = (i) => (i / (N - 1)) * VW;
  const Y = (v) => PAD + (1 - (v - lo) / (hi - lo)) * (VH - PAD * 2);
  const pts = m.v.map((v, i) => [X(i), Y(v)]);
  const path = (a) => a.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('');
  const svg = cards[k].querySelector('.bks-sync-plot svg');
  const post = pts.slice(D.events[0]);
  svg.querySelector('.bks-sync-pre').setAttribute('d', path(pts.slice(0, D.events[0] + 1)));
  svg.querySelector('.bks-sync-line').setAttribute('d', path(post));
  svg.querySelector('.bks-sync-area').setAttribute('d', path(post) + 'L' + VW + ' ' + VH + 'L' + post[0][0].toFixed(1) + ' ' + VH + 'Z');
  svg.querySelector('.bks-sync-ev').setAttribute('d', D.events.map((w) => 'M' + X(w).toFixed(1) + ' 0V' + VH).join(''));
  return { ys: pts.map((p) => p[1] / VH) };
});

/* ---------- one week index, applied everywhere ---------- */
let week = N - 1;
function setWeek(w) {
  w = Math.max(0, Math.min(N - 1, w));
  if (w === week && root.style.getPropertyValue('--bks-sync-x')) return;
  week = w;
  root.style.setProperty('--bks-sync-x', (w / (N - 1)).toFixed(4));
  wkEl.textContent = w + 1;
  evks.forEach((e) => e.classList.toggle('is-past', w >= +e.dataset.w));
  D.metrics.forEach((m, k) => {
    const c = cards[k], v = m.v[w], base = m.v[0];
    c.style.setProperty('--bks-sync-y', geo[k].ys[w].toFixed(4));
    c.querySelector('.bks-sync-num').textContent = FMT[m.fmt](v);
    const d = c.querySelector('.bks-sync-delta'), b = d.querySelector('b');
    if (w === 0) {
      b.textContent = 'Baseline';
      d.dataset.base = 'true'; d.dataset.good = 'false';
    } else {
      const pct = Math.round((v / base - 1) * 100);
      b.textContent = (pct >= 0 ? '+' : '−') + Math.abs(pct) + '%';
      d.dataset.base = 'false';
      d.dataset.good = String(m.better === 'up' ? pct > 0 : pct < 0);
    }
    plots[k].setAttribute('aria-valuenow', w + 1);
    plots[k].setAttribute('aria-valuetext', 'Week ' + (w + 1) + ': ' + FMT[m.fmt](v) + SPOKEN[m.fmt]);
  });
}

/* ---------- pointer: scrub any chart, the rest follow ---------- */
let dragging = null, leaveT = 0;
const weekAt = (plot, clientX) => {
  const r = plot.getBoundingClientRect();
  return Math.round(((clientX - r.left) / r.width) * (N - 1));
};
plots.forEach((p) => {
  p.addEventListener('pointerenter', () => { clearTimeout(leaveT); root.classList.add('is-scrub'); });
  p.addEventListener('pointermove', (e) => { if (!dragging || dragging === p) setWeek(weekAt(p, e.clientX)); });
  p.addEventListener('pointerdown', (e) => {
    dragging = p;
    p.setPointerCapture(e.pointerId);
    root.classList.add('is-scrub');
    setWeek(weekAt(p, e.clientX));
  });
  const end = () => { dragging = null; };
  p.addEventListener('pointerup', end);
  p.addEventListener('pointercancel', end);
  p.addEventListener('pointerleave', () => {
    if (dragging) return;
    // glide home to the latest week, slowly enough to read as a return
    leaveT = setTimeout(() => {
      if (!root.isConnected) return;
      root.classList.remove('is-scrub');
      if (!root.contains(document.activeElement) || !document.activeElement.classList.contains('bks-sync-plot')) setWeek(N - 1);
    }, 260);
  });
  p.addEventListener('keydown', (e) => {
    const step = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1, PageUp: 4, PageDown: -4 }[e.key];
    let w = null;
    if (step !== undefined) w = week + step;
    else if (e.key === 'Home') w = 0;
    else if (e.key === 'End') w = N - 1;
    if (w === null) return;
    e.preventDefault();
    root.classList.remove('is-scrub');
    setWeek(w);
  });
});

/* crosshairs move with transform, so each plot needs its own pixel size */
const ro = new ResizeObserver((entries) => {
  if (!root.isConnected) { ro.disconnect(); return; }
  entries.forEach((en) => {
    const el = en.target;
    el.style.setProperty('--bks-sync-w', el.clientWidth);
    el.style.setProperty('--bks-sync-h', el.clientHeight);
  });
});
plots.forEach((p) => ro.observe(p));

setWeek(N - 1);

