@property --bks-road-yr { syntax: "<integer>"; inherits: true; initial-value: 2019; }
@property --bks-road-stop { syntax: "<integer>"; inherits: true; initial-value: 0; }
@property --bks-road-lit { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --bks-road-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.bks-road {
  /* re-theme with these four */
  --bks-road-sky: oklch(95.5% 0.032 145);
  --bks-road-ink: oklch(26% 0.035 255);
  --bks-road-accent: oklch(67% 0.18 33);
  --bks-road-asphalt: oklch(40% 0.03 255);

  --bks-road-paper: oklch(99.3% 0.006 95);
  --bks-road-muted: color-mix(in oklch, var(--bks-road-ink) 62%, var(--bks-road-sky));
  --bks-road-grass: color-mix(in oklch, oklch(80% 0.11 140) 55%, var(--bks-road-sky));
  --bks-road-leaf: oklch(68% 0.12 150);
  --bks-road-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --bks-road-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bks-road-pop: linear(0, 0.058, 0.205, 0.398, 0.604, 0.797, 0.959, 1.08, 1.159, 1.198, 1.204, 1.186, 1.153, 1.112, 1.07, 1.032, 1.001, 0.978, 0.964, 0.958, 0.959, 0.963, 0.971, 0.98, 0.988, 0.995, 1.001, 1.005, 1.008, 1.009, 1.008, 1.007, 1.005, 1.004, 1);

  container-type: inline-size;
  timeline-scope: --bks-road-tl;
  box-sizing: border-box;
  width: 100%;
  background: var(--bks-road-paper);
  color: var(--bks-road-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
}

.bks-road-in {
  padding: clamp(36px, 6cqi, 80px) clamp(16px, 5cqi, 64px) clamp(28px, 5cqi, 64px);
  display: grid; gap: clamp(20px, 3cqi, 32px);
}

/* ---------- header ---------- */
.bks-road-head {
  display: grid; gap: 12px 40px;
  grid-template-areas: "kicker" "title" "lede" "meter";
}
.bks-road-kicker {
  grid-area: kicker;
  display: inline-flex; align-items: center; gap: 8px;
  font: 700 12.5px/1 var(--bks-road-round); letter-spacing: .02em;
  color: var(--bks-road-accent);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
}
.bks-road-title {
  grid-area: title;
  font: 800 clamp(32px, 4cqi + 16px, 60px)/1 var(--bks-road-round);
  letter-spacing: -.03em;
  text-wrap: balance;
  max-width: 15ch;
}
.bks-road-lede { grid-area: lede; color: var(--bks-road-muted); max-width: 46ch; text-wrap: pretty; }

.bks-road-meter {
  grid-area: meter;
  display: grid; grid-template-columns: auto auto 1fr; align-items: end; gap: 8px 22px;
  font-family: var(--bks-road-round);
  & span { display: block; font: 600 11px/1 var(--bks-road-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bks-road-muted); margin-bottom: 6px; }
  & b { font-size: clamp(30px, 2cqi + 20px, 40px); font-weight: 800; line-height: .9; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & small { font-size: 14px; font-weight: 700; color: var(--bks-road-muted); margin-left: 4px; }
}
/* the year and the stop count are integers animated by the scroll timeline and printed with counters */
.bks-road-year b { counter-reset: bks-road-yr var(--bks-road-yr); &::after { content: counter(bks-road-yr); } }
.bks-road-stops b { counter-reset: bks-road-st var(--bks-road-stop); &::after { content: counter(bks-road-st); } }
.bks-road-bar {
  align-self: center;
  height: 10px; border-radius: 99px;
  background: color-mix(in oklch, var(--bks-road-ink) 9%, var(--bks-road-paper));
  overflow: hidden;
  margin-bottom: 6px;
  & i { display: block; height: 100%; border-radius: inherit; background: var(--bks-road-accent); transform-origin: left; scale: var(--bks-road-p) 1; }
}

/* ---------- the road ---------- */
.bks-road-track {
  position: relative;
  overflow-x: auto; overflow-y: hidden;
  overscroll-behavior-x: contain;
  scroll-timeline: --bks-road-tl inline;
  border-radius: 26px;
  background: var(--bks-road-sky);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bks-road-ink) 8%, transparent);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--bks-road-ink) 25%, transparent) transparent;
  cursor: grab;
  &:focus-visible { outline: 3px solid var(--bks-road-accent); outline-offset: 3px; }
  &.is-drag { cursor: grabbing; user-select: none; }
}
.bks-road-world { position: relative; }
.bks-road-svg { position: absolute; inset: 0; display: block; }
.bks-road-field { fill: var(--bks-road-grass); &.is-b { fill: color-mix(in oklch, var(--bks-road-grass) 60%, var(--bks-road-sky)); } }
.bks-road-edge { fill: none; stroke: var(--bks-road-paper); stroke-width: 42; stroke-linecap: round; }
.bks-road-asphalt { fill: none; stroke: var(--bks-road-asphalt); stroke-width: 32; stroke-linecap: round; }
.bks-road-lane { fill: none; stroke: color-mix(in oklch, var(--bks-road-paper) 85%, transparent); stroke-width: 2.5; stroke-dasharray: 14 12; stroke-linecap: round; }
.bks-road-tree {
  & rect { fill: oklch(52% 0.06 60); }
  & circle { fill: var(--bks-road-leaf); }
  &:nth-of-type(3n) circle { fill: color-mix(in oklch, var(--bks-road-leaf) 75%, oklch(85% 0.12 120)); }
}
.bks-road-house {
  & .bks-road-wall { fill: oklch(93% 0.04 80); stroke: color-mix(in oklch, var(--bks-road-ink) 25%, transparent); stroke-width: 1; }
  & .bks-road-roof { fill: color-mix(in oklch, var(--bks-road-accent) 70%, oklch(70% 0.08 40)); }
  & .bks-road-door { fill: color-mix(in oklch, var(--bks-road-ink) 60%, transparent); }
}
.bks-road-depot {
  & rect { fill: var(--bks-road-paper); stroke: var(--bks-road-ink); stroke-width: 1.5; }
  & path { fill: var(--bks-road-ink); }
  & .bks-road-door { fill: color-mix(in oklch, var(--bks-road-ink) 20%, var(--bks-road-paper)); }
}
.bks-road-flag {
  & .bks-road-pole { stroke: var(--bks-road-ink); stroke-width: 2.5; stroke-linecap: round; fill: none; }
  & path:not(.bks-road-pole) { fill: var(--bks-road-accent); }
}
.bks-road-start, .bks-road-end {
  position: absolute;
  font: 700 12px/1.3 var(--bks-road-round);
  color: var(--bks-road-ink);
}
.bks-road-end { width: 170px; font-size: 14px; text-wrap: balance; }

/* signposts */
.bks-road-sign {
  --bks-road-lit: 0;
  position: absolute;
  width: 214px; min-height: 112px;
  padding: 11px 13px 12px;
  border-radius: 16px;
  background: var(--bks-road-paper);
  box-shadow:
    0 0 0 2px color-mix(in oklch, var(--bks-road-ink) calc(14% + var(--bks-road-lit) * 86%), transparent),
    0 calc(2px + var(--bks-road-lit) * 8px) calc(6px + var(--bks-road-lit) * 18px) -6px color-mix(in oklch, var(--bks-road-ink) 40%, transparent);
  translate: 0 calc((1 - var(--bks-road-lit)) * 4px);
  & h3 { font: 800 16px/1.15 var(--bks-road-round); letter-spacing: -.01em; margin-top: 4px; text-wrap: balance; }
}
.bks-road-date {
  display: inline-block;
  font: 700 11px/1 var(--bks-road-mono); letter-spacing: .02em;
  padding: 4px 7px; border-radius: 99px;
  background: color-mix(in oklch, var(--bks-road-accent) calc(var(--bks-road-lit) * 100%), color-mix(in oklch, var(--bks-road-ink) 8%, var(--bks-road-paper)));
  color: color-mix(in oklch, var(--bks-road-paper) calc(var(--bks-road-lit) * 100%), var(--bks-road-ink));
}
.bks-road-txt { font-size: 12.5px; line-height: 1.4; color: var(--bks-road-muted); margin-top: 4px; text-wrap: pretty; }
.bks-road-post {
  position: absolute; left: calc(50% - 2px); width: 4px; border-radius: 2px;
  background: color-mix(in oklch, var(--bks-road-ink) 70%, transparent);
  .bks-road-sign.is-up & { top: 100%; }
  .bks-road-sign.is-down & { bottom: 100%; }
}
.bks-road-stamp {
  position: absolute; right: -10px; top: -12px;
  display: inline-flex; align-items: center; gap: 3px;
  padding: 4px 8px 4px 5px; border-radius: 99px;
  background: var(--bks-road-accent); color: var(--bks-road-paper);
  font: 800 10.5px/1 var(--bks-road-round); letter-spacing: .02em; text-transform: uppercase;
  rotate: calc((1 - var(--bks-road-lit)) * -40deg + 8deg);
  scale: var(--bks-road-lit);
  & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
}

/* the van */
.bks-road-van {
  position: absolute; left: 0; top: 0;
  width: 64px; height: 34px;
  offset-anchor: 50% 74%;
  offset-rotate: auto;
  offset-distance: calc(var(--bks-road-p) * 100%);
  z-index: 2;
  filter: drop-shadow(0 4px 3px color-mix(in oklch, var(--bks-road-ink) 30%, transparent));
  & svg { width: 100%; height: 100%; display: block; overflow: visible; }
}
.bks-road-body { fill: var(--bks-road-accent); }
.bks-road-glass { fill: color-mix(in oklch, var(--bks-road-paper) 80%, oklch(85% 0.05 230)); }
.bks-road-stripe { stroke: var(--bks-road-paper); stroke-width: 2; stroke-linecap: round; fill: none; }
.bks-road-wheel {
  rotate: calc(var(--bks-road-p) * 5400deg);
  & circle { fill: var(--bks-road-ink); stroke: var(--bks-road-paper); stroke-width: 1.4; }
  & path { stroke: color-mix(in oklch, var(--bks-road-paper) 70%, transparent); stroke-width: 1.2; }
}

/* milestone dots */
.bks-road-dots {
  position: relative;
  display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none;
  padding: 2px;
  &::-webkit-scrollbar { display: none; }
}
.bks-road-dot {
  flex: none;
  padding: 7px 11px; border-radius: 99px;
  border: 1.5px solid color-mix(in oklch, var(--bks-road-ink) 14%, var(--bks-road-paper));
  background: var(--bks-road-paper);
  font: 700 12px/1 var(--bks-road-round);
  color: var(--bks-road-muted);
  cursor: pointer;
  transition: background-color .25s, color .25s, border-color .25s, scale .4s var(--bks-road-pop);
