// Scroll progress at which the van reaches each signpost, measured along the road's arc length.
const D = {"p": [0.1021, 0.2504, 0.3921, 0.5359, 0.6784, 0.8213, 0.953], "years": [2019, 2019, 2020, 2021, 2022, 2024, 2026]};
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const track = root.querySelector('.bks-road-track');
const dots = [...root.querySelectorAll('.bks-road-dot')];
const signs = [...root.querySelectorAll('.bks-road-sign')];
const yearB = root.querySelector('.bks-road-year b');
const stopB = root.querySelector('.bks-road-stops b');

// Scroll-driven animations do the work where supported; otherwise the same variables are written from scroll.
const native = typeof CSS !== 'undefined' && CSS.supports('animation-timeline: scroll()');
if (!native) root.classList.add('is-js');

let cur = -1;
const maxScroll = () => Math.max(0, track.scrollWidth - track.clientWidth);
const clamp01 = (v) => Math.max(0, Math.min(1, v));

function sync() {
  const max = maxScroll(), p = max ? track.scrollLeft / max : 0;
  let k = 0;
  D.p.forEach((pm, i) => { if (p >= pm - 0.035) k = i; });
  if (k !== cur) {
    cur = k;
    dots.forEach((d, i) => { if (i === k) d.setAttribute('aria-current', 'step'); else d.removeAttribute('aria-current'); });
    // keep the current stop visible in the (possibly overflowing) row of dots
    const d = dots[k], nav = d.parentElement;
    if (nav.scrollWidth > nav.clientWidth) nav.scrollTo({ left: d.offsetLeft - (nav.clientWidth - d.offsetWidth) / 2, behavior: reduce.matches ? 'auto' : 'smooth' });
  }
  if (native) return;
  root.style.setProperty('--bks-road-p', p.toFixed(4));
  signs.forEach((s, i) => s.style.setProperty('--bks-road-lit', clamp01((p - (D.p[i] - 0.026)) / 0.026).toFixed(3)));
  let yr = 2019, st = 0;
  D.p.forEach((pm, i) => { if (p >= pm) { yr = D.years[i]; st = i + 1; } });
  yearB.style.setProperty('--bks-road-yr', yr);
  stopB.style.setProperty('--bks-road-stop', st);
}

let queued = false;
track.addEventListener('scroll', () => {
  if (queued) return;
  queued = true;
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    queued = false;
    sync();
  });
}, { passive: true });

/* jump to a stop: scroll so the van arrives exactly at the sign */
function go(k) {
  track.scrollTo({ left: D.p[k] * maxScroll(), behavior: reduce.matches ? 'auto' : 'smooth' });
}
dots.forEach((d, k) => d.addEventListener('click', () => go(k)));
root.querySelector('.bks-road-dots').addEventListener('keydown', (e) => {
  const i = dots.indexOf(document.activeElement);
  if (i < 0) return;
  const j = { ArrowRight: Math.min(dots.length - 1, i + 1), ArrowLeft: Math.max(0, i - 1), Home: 0, End: dots.length - 1 }[e.key];
  if (j === undefined) return;
  e.preventDefault();
  dots.forEach((d, n) => { d.tabIndex = n === j ? 0 : -1; });
  dots[j].focus();
  go(j);
});

/* a vertical wheel drives the road, but hands back to the page at either end */
track.addEventListener('wheel', (e) => {
  if (Math.abs(e.deltaY) <= Math.abs(e.deltaX) || e.ctrlKey) return;
  const max = maxScroll();
  if ((e.deltaY > 0 && track.scrollLeft >= max - 1) || (e.deltaY < 0 && track.scrollLeft <= 0)) return;
  e.preventDefault();
  track.scrollLeft += e.deltaY;
}, { passive: false });

/* drag to scroll with a mouse; touch and pens already pan natively */
let drag = null;
track.addEventListener('pointerdown', (e) => {
  if (e.pointerType !== 'mouse' || e.button !== 0) return;
  drag = { x: e.clientX, left: track.scrollLeft };
  track.setPointerCapture(e.pointerId);
});
track.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const dx = e.clientX - drag.x;
  if (Math.abs(dx) > 3) track.classList.add('is-drag');
  track.scrollLeft = drag.left - dx;
});
const endDrag = () => { drag = null; track.classList.remove('is-drag'); };
track.addEventListener('pointerup', endDrag);
track.addEventListener('pointercancel', endDrag);

sync();
